INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0GK18YLP3','3-Tier Spice Rack Organizer, 13"-21.5" Expandable Spice Organization Shelf, Metal Seasoning Organizer for Kitchen Countertop or Pantry, Slip-Resistant Design for Jars and Bottles, Black','3-tier-spice-rack-organizer-13-215-expandable-spice-organiza-b0gk18ylp3','Symeno Select','Spice & Pantry Tools',28.99,'【Tiered Design & Expandable Spice Rack Organizer】This spice rack extends from 13 to 21.5 width, effortlessly fitting in kitchen cabinets, on countertops, inside cupboards or pantries. Each tier offers a generous depth of 2.95 inches (7.5 cm)—fit for storing 6-8 oz spice jars, seasoning bottles, cans, and more. 【Clear Visibility & Organization】Unlike flat spice shelf, our 3‑tier design keeps all labels fully visible at a glance. Built‑in non‑slip guardrails hold bottles & jars securely, keeping your countertop neat. All items are easy to see, access, and store. 【Custom Fit for Your Space】PEEKUP spice rack organizer for cabinet: adjustable width extends from 13" to 21.5" to fit your space, 9.45" depth & 4.5" height. Free-standing spice racks fits kitchen, pantry, bathroom and even garage, adapting to any space as you need. 【Durable Metal Material】Crafted from premium powder-coated metal, this seasoning organizer resists rust and prevents bending. The smooth surface wipes clean in seconds with a damp cloth for effortless daily maintenance. Each shelf holds up to 13 lbs (6 kg)—making it far sturdier than plastic or acrylic alternatives. 【Ideal Gift for Home Lovers】Looking for a useful yet stylish housewarming gift? This spice rack is suit for anyone who loves grilling, cooking, or just keeping their kitchen neat and organized. A great choice for birthdays, holidays, or housewarming—give the gift of a tidy kitchen.','["https://m.media-amazon.com/image