INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B07DFRSBFC','PATRIOT Set of 25 Hexagon Glass Spice Jars with Shaker Lids and Labels for Refrigerator, Kitchen, RV Travel Trailer Magnetic Containers','patriot-set-of-25-hexagon-glass-spice-jars-with-shaker-lids-b07dfrsbfc','PATRIOT CREATIVE','Spice & Pantry Tools',44.98,'COMPLETE MAGNETIC SPICE RACK SET OF 25 SMALL HEXAGON GLASS SPICE JARS FOR CREATE A DIY HANGING SPICE RACK ON YOUR OWN FRIDGE, REFRIGERATOR, CABINET AND WALL MOUNT: 25 Complete Sets including 25 pcs Clear Hexagon Glass Jars with Airtight & Leak Proof Magnetic Lids + 25 pcs Shakers + Total 320 pcs Waterproof & Oil Resistant Pre-printed Spice Labels (160 Transparent + 160 Black).. HIGH STRENGTH MAGNETS WITH STYLISH HEXAGON JARS SAVING YOUR VALUABLE KITCHEN SPACE: Our spice jars include an ultra-strong neodymium magnet securely enclosed under each lid. This ensures a strong stick to any metal surface, including the swinging fridge door, side of the refrigerator, backsplash magnetic spice jar metal board and more. The high strength also makes our jars the perfect storage solution for mobile homes, RVs and boats. PERFECT SPACE SAVER SPICE CONTAINER SET!. PREMIUM COMMERCIAL GRADE HEAVY DUTY HEXAGON GLASS JAR WITH AIRTIGHT SCREW LIDS DESIGN: Our unique glass jar design makes for a beautiful look in your kitchen while also saving space vs. a round or square design jars. Each empty airtight small jars measure 2” tall x 1.75” wide and hold a shy 1/4 cup volume. Our airtight screw lid is designed for preventing any pop off, loose lids issue. Our lids always stay on securely.. ALL ACCESSORY INCLUDED IN ONE BOX: SIFT AND POUR SHAKERS for dual purpose. Pouring out granulated spices and herbs on one side and sprinkling powdered spices on the other. You can season your dishes without getting your hand dirty. T