INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FPJ1Q5H6','White Corner Floating Shelves for Wall – Set of 4, Rounded Wood Wall Mounted Corner Shelf with Hardware, Space Saving Decorative Storage for Kids Room, Bathroom, Living Room, Office – White','white-corner-floating-shelves-for-wall-set-of-4-rounded-wood-b0fpj1q5h6','Symeno Select','Wall & Décor',34.99,'MAXIMIZE UNUSED CORNERS WITH STYLE: Transform empty wall corners into beautiful storage spots. These floating shelves are perfect for holding books, toys, decor, or toiletries – helping you organize your space while adding a clean, modern look to any room.. BUILT FOR STRENGTH AND LONG-LASTING USE: Made from high-quality wood, these corner shelves are durable, heavy-duty, and built to support everyday use. Designed to hold your essentials without sagging or warping, even in humid areas like bathrooms.. CHILD-FRIENDLY ROUNDED EDGES: Safety matters, especially in kids'' rooms. These wall-mounted shelves feature smooth, rounded corners to prevent bumps and injuries, making them ideal for children''s bedrooms, playrooms, or nurseries.. SPACE-SAVING DESIGN FOR SMALL ROOMS: Perfect for apartments, bathrooms, dorms, or small bedrooms each shelf fits snugly into corners to free up valuable floor and counter space. Ideal for those looking to reduce clutter without sacrificing style.. EASY INSTALLATION WITH INCLUDED HARDWARE: No need to stress about mounting everything you need is included. Each shelf set comes with clear instructions and sturdy hardware, so you can hang them up quickly and securely with minimal tools.','["https://m.media-amazon.com/images/I/71Q2zif+AUL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71oIHdqvdWL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71K1-hKmcmL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71bLpWw6