INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0GGQN8YZQ','Venusmiles Corner Floating Shelves Set of 4, Wall Mounted L-Shaped Storage - Maximize Unused Corner Space in Bathroom, Kitchen, Bedroom, Office, Dark Carbonized','venusmiles-corner-floating-shelves-set-of-4-wall-mounted-l-s-b0ggqn8yzq','Symeno Select','Wall & Décor',27.74,'Transform Wasted Corners into Functional Space: Our unique L-shaped design fits perfectly into any corner, instantly adding valuable storage or display area without taking up floor space. Perfect for tight spots in bathrooms, kitchens, or beside your desk.. Sturdy & Reliable Construction: Made from solid paulownia wood with carbonized finish. Each shelf holds up to 40 lbs, safely supporting books, decor, toiletries, kitchen jars, or small plants. The included metal brackets ensure a secure wall mount.. Versatile for Any Room & Style: The rustic-chic design and neutral color complement farmhouse, modern, or industrial decor. Use the set of 4 to create a vertical display in your living room, organize spices in the kitchen, or keep bathroom essentials tidy.. Complete Set for Cohesive Look: Get a uniform, designer look instantly. This 4-piece set comes with all necessary hardware (brackets, screws, manual) for a seamless installation across multiple corners or as a grouped display.. Easy, Tool-Friendly Installation: Mount your shelves in minutes with clear instructions. The straightforward design means you can have your new storage solution up and ready to use almost immediately. We’re here to help if you have any questions.','["https://m.media-amazon.com/images/I/81pG61iVDfL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71GdXj+3CUL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81GW0TnRnRL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81mJ60x+sOL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/91NdUrH9WOL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81JlPbDhUFL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/91cPnZQyoFL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71g9P7hlnAL._AC_SL1500_.jpg"]',4.3,10,'hasdata','https://www.amazon.com/dp/B0GGQN8YZQ',1778330806,1,NULL,'["Transform Wasted Corners into Functional Space: Our unique L-shaped design fits perfectly into any corner, instantly adding valuable storage or display area without taking up floor space. Perfect for tight spots in bathrooms, kitchens, or beside your desk.","Sturdy & Reliable Construction: Made from solid paulownia wood with carbonized finish. Each shelf holds up to 40 lbs, safely supporting books, decor, toiletries, kitchen jars, or small plants. The included metal brackets ensure a secure wall mount.","Versatile for Any Room & Style: The rustic-chic design and neutral color complement farmhouse, modern, or industrial decor. Use the set of 4 to create a vertical display in your living room, organize spices in the kitchen, or keep bathroom essentials tidy.","Complete Set for Cohesive Look: Get a uniform, designer look instantly. This 4-piece set comes with all necessary hardware (brackets, screws, manual) for a seamless installation across multiple corners or as a grouped display.","Easy, Tool-Friendly Installation: Mount your shelves in minutes with clear instructions. The straightforward design means you can have your new storage solution up and ready to use almost immediately. We’re here to help if you have any questions."]');
