INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0GLXB677R','Orose 100% Mulberry Silk Luxurious Neck Scarf Headband and Hair Bandana for Women and Girls,Head Scarves, Handbags Scarf','orose-100-mulberry-silk-luxurious-neck-scarf-headband-and-ha-b0glxb677r','Symeno Select','Women''s Accessories',18.99,'【ORIGINAL DESIGN & HANDMADE】Hand-cut, featuring a unique and fashionable large bevel design, this lightweight and elegant ribbon embodies the "new trend" of the 1930s vintage style. It is an indispensable accessory for your daily look. Size: 2.7 x 70.8inch / 7*180cm.. 【PREMIUM SILK MATERIAL】100% 22 momme natural mulberry silk, crafted from smooth, lightweight silk fabric that feels soft and luxurious against skin while adding elegant style to any outfit.. 【VERSATILE STYLING】Multi-functional silk scarf can be worn as a neck scarf, headband, hair bandana, or handbag accessory for endless fashion possibilities.With multiple DIY styling options, choose the one that suits your occasion, whether it''s a birthday party, travel, or business office.. 【PERFECT FOR WOMEN AND GIRLS】Fashion-forward design suitable for all ages, making it an ideal accessory for daily wear, special occasions, or as a thoughtful gift.. 【COMPACT AND PORTABLE】Lightweight construction allows for easy folding and storage in purses or bags, making it convenient to carry and style on the go.. 【GIFT IDEAS】Think bridesmaids, birthday, girls trip, favorite things party, Christmas stocking stuffers... BEST GIFT EVER.','["https://m.media-amazon.com/images/I/31pyiE6obAL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61CLV6MgiwL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/61HcYxYD5xL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61bHOLJEglL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71ElqxwB33L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71HTXfweQfL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/41jhJ0A4XWL._AC_.jpg","https://m.media-amazon.com/images/I/71SOcaHe22L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61xVZbDigBL._AC_SL1500_.jpg"]',4.6,30,'hasdata','https://www.amazon.com/dp/B0GLXB677R',1778330960,1,NULL,'["【ORIGINAL DESIGN & HANDMADE】Hand-cut, featuring a unique and fashionable large bevel design, this lightweight and elegant ribbon embodies the \"new trend\" of the 1930s vintage style. It is an indispensable accessory for your daily look. Size: 2.7 x 70.8inch / 7*180cm.","【PREMIUM SILK MATERIAL】100% 22 momme natural mulberry silk, crafted from smooth, lightweight silk fabric that feels soft and luxurious against skin while adding elegant style to any outfit.","【VERSATILE STYLING】Multi-functional silk scarf can be worn as a neck scarf, headband, hair bandana, or handbag accessory for endless fashion possibilities.With multiple DIY styling options, choose the one that suits your occasion, whether it''s a birthday party, travel, or business office.","【PERFECT FOR WOMEN AND GIRLS】Fashion-forward design suitable for all ages, making it an ideal accessory for daily wear, special occasions, or as a thoughtful gift.","【COMPACT AND PORTABLE】Lightweight construction allows for easy folding and storage in purses or bags, making it convenient to carry and style on the go.","【GIFT IDEAS】Think bridesmaids, birthday, girls trip, favorite things party, Christmas stocking stuffers... BEST GIFT EVER."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0BLHC5RWG','TUMELLA Strongest Windproof Travel Umbrella (Compact, Superior & Beautiful), Small, Wind-Tested, Light & Portable, Automatic Folding Rain Umbrella, Durable Premium Grip, Fits Car and Backpack','tumella-strongest-windproof-travel-umbrella-compact-superior-b0blhc5rwg','Symeno Select','Women''s Accessories',19.99,'Tumella Umbrella - Makes You Smile in the Rain. Most umbrellas are boring and unreliable, breaking and flipping with the slightest breeze. Sturdy umbrellas are too big and heavy, and impossible to travel with. Tumella brings to you the best of both worlds, a small mini umbrella, but extremely sturdy with unmatched wind protection. Carefully tested to withstand winds as strong as 70MPH (hurricane strength). Our one-of-a-kind umbrella will last for years to come. We''ve added unique features and vibrant designs to give you an exceptional umbrella that’s easy to carry and will be there for you in moments when you need it most. Discover the unique features & benefits of the Tumella travel umbrella: 1. Superb Sturdiness - Nine unbreakable fiberglass ribs made with new ultra-flex tech 2026, 2. Waterproof and Drip Proof coating to keep you and your surroundings dry, 3. Tested & Incomparable Wind Protection, 4. Portable and super easy to use with just one hand -- comfortable even for kids, 5. Unique & vibrant designs that will match your style and make you smile on a rainy day. Choose stunning images from floral to stellar. We’re from the Netherlands, and mother nature has taught us how to master the rain to bring you an umbrella for any occasion. Stay dry and smile in the rain with Tumella','["https://m.media-amazon.com/images/I/81zF6DJmAEL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/819MgihdxAL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/8165lM4v7GL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81hLbSGK9OL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/910D55z7BVL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71R8JyqiYkL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61cHQZWVW2L._AC_.jpg"]',4.5,19373,'hasdata','https://www.amazon.com/dp/B0BLHC5RWG',1778330983,1,NULL,'["UPGRADED & UNMATCHED WIND AND WATER PROTECTION: Waterproof coating shields you from bad weather. We added a vented double canopy that allows wind to pass through, to securely and conveniently withstand even the harshest weather. Unlike other umbrellas with partial fiberglass ribs, our full fiberglass ribs may bend but will easily bounce back in shape, without breaking (aluminum) or bending (metal).","LIGHTWEIGHT, EASY ONE-HANDED USE, SMALL & PORTABLE: Take this compact umbrella for travel with you wherever you go. So versatile and simple to use, with just the touch of a button, you can automatically open or close your Tumella. It fits perfectly in your backpack, purse, or car door, with just 11 by 2.75 inches in size, weights less than 1 lb, while offering a huge coverage of 42 inch.","40+ UNIQUE, VIBRANT & BEAUTIFUL GIFT IDEAS: Dress up your look with a unique companion umbrella. Choose from our vibrant selection of elegant and nature-based designs. Enjoy long-lasting, high-quality printed art while protected from the elements. Gift your loved ones a Tumella (or a few), a superior and fashionable travel umbrella for all seasons and all weather.","WE OFFER LIFELONG CARE AND SUPPORT if you ever have a concern with your Tumella. We want it to be your go-to for years to come—rain or shine. That’s why every part is carefully selected, thoroughly tested, and thoughtfully assembled to meet our high standards of durability and style."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B078PD34VG','SIEPASA Compact Travel Umbrella - Windproof Auto Open/Close, Small Folding Umbrella for Rain - Lightweight & Durable with Fiberglass Frame, Waterproof Canopy - Fits Backpack, Purse, Suitcase. (Black)','siepasa-compact-travel-umbrella-windproof-auto-openclose-sma-b078pd34vg','SIEPASA','Women''s Accessories',8.99,'Upgraded Automatic Umbrella- Easy one hand operation with one auto open & close button, simply touch it to expand or collapse,. Windproof - 8 reinforced fiberglass ribs flex slightly in powerful gusts keeping the umbrella from turning inside out and leaving you soaked,. Compact & Ultra lightweight- At 11.8” when compacted, easily fits in your work bag, purse, backpack, car container etc. Weighs 14 ounce with a handy wrist string for convenient carrying around,. Waterproof- Put the technology of Teflon to work for you! Waterproof and instantly dry, our Travel Umbrella defends against the elements like nothing else,. Ideal Gift & Quality Guarantee: This compact travel umbrella is portable for your travel, it''s also a creative gift for your parents, friends, colleagues and etc. Using this folding umbrella, you are always protected from rain, wind and UV. If anything goes wrong with your umbrella, we will send you a replacement absolutely free, no return required.','["https://m.media-amazon.com/images/I/71jbTYmz7EL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71cwy-ApyOL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/717OMIIE8YL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61DgXZN+ImL._AC_SL1024_.jpg","https://m.media-amazon.com/images/I/71RuH4LClML._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71T-bweyduL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71G9Oria-6L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71SJLcRGDWL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71vAzKtjZIL._AC_SL1500_.jpg"]',4.4,10334,'hasdata','https://www.amazon.com/dp/B078PD34VG',1778330991,1,NULL,'["Upgraded Automatic Umbrella- Easy one hand operation with one auto open & close button, simply touch it to expand or collapse,","Windproof - 8 reinforced fiberglass ribs flex slightly in powerful gusts keeping the umbrella from turning inside out and leaving you soaked,","Compact & Ultra lightweight- At 11.8” when compacted, easily fits in your work bag, purse, backpack, car container etc. Weighs 14 ounce with a handy wrist string for convenient carrying around,","Waterproof- Put the technology of Teflon to work for you! Waterproof and instantly dry, our Travel Umbrella defends against the elements like nothing else,","Ideal Gift & Quality Guarantee: This compact travel umbrella is portable for your travel, it''s also a creative gift for your parents, friends, colleagues and etc. Using this folding umbrella, you are always protected from rain, wind and UV. If anything goes wrong with your umbrella, we will send you a replacement absolutely free, no return required."]');
