INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0CZ75PS8M','Aveniee Travel Makeup Bag Small, Vegan Leather Cosmetic Pouch for Purse, Wide-open Toiletry Organizer with Dividers & Zipper for Women-Beige','aveniee-travel-makeup-bag-small-vegan-leather-cosmetic-pouch-b0cz75ps8m','Symeno Select','Bags & Pouches',12.99,'Premium Material & 4 Pockets: This small makeup bag, measuring 6.9(L) x 3(W) x 4.9(H) inches, is your perfect travel accessory. Made from premium vegan leather, this makeup pouch for purse features a spacious main compartment for toiletries and cosmetics, plus 3 side pockets for essentials like lipstick and eye shadow. Stylish & functional!. Stand up Design & Large Opening: The Aveniee makeup bag for purse features a self-standing design, keeping it upright on any surface. The spacious interior of the small cosmetic bag offers ample storage, while the large opening allows easy access to cosmetics. The beige color and gold zippers add a sophisticated touch. Sophistication with Comfort: Indulge in luxury with this soft, smooth vegan leather of the travel makeup bag. The large toiletry bag comes with dual zippers, while the small pouch has a single zipper, ensuring smooth opening and closing for both cases. Exquisite stitching and superior lining elevate its elegant design, perfect for travel.. Versatile & Easy to Clean: This portable zipper pouch is the ultimate pick for every traveler, doubling as a daily purse organizer, makeup pouch, tech accessories bag, or travel accessories bag. Just a quick wipe with a damp cloth and it''ll be as good as new. Whether you''re at home or on the go, the Aveniee makeup case combines functionality with elegance, making it the perfect companion for all your beauty needs. Perfect Gift: Our makeup bags are beautifully wrapped in soft tissue paper to keep them wrinkle-free and picture-perfect! They make the ideal gift for Christmas, birthdays, or Valentine’s Day. With their chic design and practical functionality, they’re the perfect choice for any woman—whether it''s for a friend, family member, or your BFF','["https://m.media-amazon.com/images/I/81dKY15+qbL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81i0C8AU4wL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81RMywLHSML._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81xOFianv2L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/612cR4mOlhL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81kOnwt-TKL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71RSfQCRs1L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81o3pEON3RL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71Fgpl3qdXL._AC_SL1500_.jpg"]',4.6,234,'hasdata','https://www.amazon.com/dp/B0CZ75PS8M',1778331106,1,NULL,'["Premium Material & 4 Pockets: This small makeup bag, measuring 6.9(L) x 3(W) x 4.9(H) inches, is your perfect travel accessory. Made from premium vegan leather, this makeup pouch for purse features a spacious main compartment for toiletries and cosmetics, plus 3 side pockets for essentials like lipstick and eye shadow. Stylish & functional!","Stand up Design & Large Opening: The Aveniee makeup bag for purse features a self-standing design, keeping it upright on any surface. The spacious interior of the small cosmetic bag offers ample storage, while the large opening allows easy access to cosmetics. The beige color and gold zippers add a sophisticated touch","Sophistication with Comfort: Indulge in luxury with this soft, smooth vegan leather of the travel makeup bag. The large toiletry bag comes with dual zippers, while the small pouch has a single zipper, ensuring smooth opening and closing for both cases. Exquisite stitching and superior lining elevate its elegant design, perfect for travel.","Versatile & Easy to Clean: This portable zipper pouch is the ultimate pick for every traveler, doubling as a daily purse organizer, makeup pouch, tech accessories bag, or travel accessories bag. Just a quick wipe with a damp cloth and it''ll be as good as new. Whether you''re at home or on the go, the Aveniee makeup case combines functionality with elegance, making it the perfect companion for all your beauty needs","Perfect Gift: Our makeup bags are beautifully wrapped in soft tissue paper to keep them wrinkle-free and picture-perfect! They make the ideal gift for Christmas, birthdays, or Valentine’s Day. With their chic design and practical functionality, they’re the perfect choice for any woman—whether it''s for a friend, family member, or your BFF"]');
