INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FN3T3Q1G','Vtopmart 4 Pack 18QT Clear Stackable Storage Drawers,Easily Assemble Closet Organizers,Plastic Storage Bins for Bathroom,Cabinet,Kitchen Pantry,Under Sink Organization(Medium)','vtopmart-4-pack-18qt-clear-stackable-storage-drawerseasily-a-b0fn3t3q1g','Vtopmart','Home Organization',42.49,'【Space Saving】The plastic storage drawers save space without taking up too much floor area. Designed to maximize storage under the walk-in closet, they feature smooth-glide drawers for easy access, allowing you to effortlessly slide them in and out. Perfect for organizing clothing, bedding, and out-of-season essentials.. 【Large Capacity】Each acrylic storage bins measures 12 x 12 x 8 inches (front width x depth x height) and holds up to 18 quarts. These plastic storage bins are built to fit just about anything you can think of, from clothes and bedding to snacks, medicine, cleaning supplies and all those random odds and ends.. 【Stackable Design】The stackable drawers allow you to customize storage in any space by combining varying numbers of units - perfect for closet,bathroom,kitchen pantries,medicine cabinets or under-sink organization.. 【Clear View】Made from durable, crystal-clear PP material, the transparent drawer design provides instant visibility of contents—no more rummaging through storage. The scratch-resistant surface ensures long-lasting clarity while maintaining a sleek, modern aesthetic in any space.. 【Easy Assembly】The storage drawers can be fully assembled in just a few minutes. First, set up the outer frame, then install the drawer,then sliding it along the track into the frame — and have done!','["https://m.media-amazon.com/images/I/71lYpUjHnyL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/710Gu2Z3hRL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/91cXVhlUTjL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/91Wg6z-yYfL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81XY6-gBYbL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81TxX-tIQ+L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/813QW8lL36L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/918usUhWY0L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81goesuMjZL._AC_SL1500_.jpg"]',4.7,181,'hasdata','https://www.amazon.com/dp/B0FN3T3Q1G',1778332206,1,NULL,'["【Space Saving】The plastic storage drawers save space without taking up too much floor area. Designed to maximize storage under the walk-in closet, they feature smooth-glide drawers for easy access, allowing you to effortlessly slide them in and out. Perfect for organizing clothing, bedding, and out-of-season essentials.","【Large Capacity】Each acrylic storage bins measures 12 x 12 x 8 inches (front width x depth x height) and holds up to 18 quarts. These plastic storage bins are built to fit just about anything you can think of, from clothes and bedding to snacks, medicine, cleaning supplies and all those random odds and ends.","【Stackable Design】The stackable drawers allow you to customize storage in any space by combining varying numbers of units - perfect for closet,bathroom,kitchen pantries,medicine cabinets or under-sink organization.","【Clear View】Made from durable, crystal-clear PP material, the transparent drawer design provides instant visibility of contents—no more rummaging through storage. The scratch-resistant surface ensures long-lasting clarity while maintaining a sleek, modern aesthetic in any space.","【Easy Assembly】The storage drawers can be fully assembled in just a few minutes. First, set up the outer frame, then install the drawer,then sliding it along the track into the frame — and have done!"]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0CZ3XCBYC','Ultimate 7 Pack 6 Size Mesh Laundry Bags Set for Delicates with AUTO-Lock Zipper, Lingerie Bags for Washing Delicates, Laundry Bags Mesh Wash Bags, Delicates Laundry Bag for Jeans,Blouse,Stocking,Bra','ultimate-7-pack-6-size-mesh-laundry-bags-set-for-delicates-w-b0cz3xcbyc','urezorgear','Cleaning & Laundry',7.59,'Upgraded Premium AUTO-Lock Zipper with Protective Elastic Band : Equipped with a premium, rust-resistant, smooth zipper featuring AUTO-Lock and an extra protective elastic band, our laundry wash bags ensure the contents remain securely enclosed throughout the washing and drying cycle. Enjoy a quieter and snag-free laundry experience with these improved features. Safeguard Your Delicates: Crafted from durable yet lightweight 70g fine mesh(unlike other 60g options), our laundry wash bags protect your garments from tangling, snagging, and pilling in the washing machine or dryer. By extending the lifespan of your delicate items, you''ll save money in the long run. Durable and Long-lasting: Constructed from stain-, stretch-, and tear-resistant 100% polyester, our laundry wash bags allow you to wash your delicates without worrying about damage in the washing machine or dryer. The fine mesh material allows soap and water to flow freely, ensuring thorough cleaning. All-in-One, One for You: Featuring 7 pieces in 6 distinct sizes and shapes, this laundry bag set offers a variety of options to suit your specific needs, making it a versatile solution for your daily cleaning tasks. The color-coded tips on each bag further enhance their functionality for organization. Beyond Just Laundry: Besides being ideal for delicate garments, these versatile bags excel at organizing luggage during travel. They''re perfect for storing various small items such as children''s toys, rubber balls, makeup, laundry accessories, clothespins, stuffed animals, and more. Warm Tips: ①Please note that to achieve better washing results, the capacity of clothes should not exceed 2/3 of the total capacity of each laundry bag. ②Remember to put the zipper under the elastic band before washing.. [Customer First, Services Foremost.]: Your satisfaction is our top priority, plz rest assured to purchase our products. If you are not satisfied with our products or have any questions, please feel free to contact us at any time, Let us remove any worry or hassle with our unique money back plus guarantee which means that if you are not totally satisfied with your product, we will refund you and you keep mesh laundry bags','["https://m.media-amazon.com/images/I/81PGtgBHGvL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71fIoM1En0L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/918PSVTlbhL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81kiWJ72E9L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81kvwlquFoL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81ZbMmXntZL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/810fP73ivzL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81TYkGMQw3L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81HPpUB5+fL._AC_SL1500_.jpg"]',4.7,2201,'hasdata','https://www.amazon.com/dp/B0CZ3XCBYC',1778332252,1,NULL,'["Upgraded Premium AUTO-Lock Zipper with Protective Elastic Band : Equipped with a premium, rust-resistant, smooth zipper featuring AUTO-Lock and an extra protective elastic band, our laundry wash bags ensure the contents remain securely enclosed throughout the washing and drying cycle. Enjoy a quieter and snag-free laundry experience with these improved features","Safeguard Your Delicates: Crafted from durable yet lightweight 70g fine mesh(unlike other 60g options), our laundry wash bags protect your garments from tangling, snagging, and pilling in the washing machine or dryer. By extending the lifespan of your delicate items, you''ll save money in the long run","Durable and Long-lasting: Constructed from stain-, stretch-, and tear-resistant 100% polyester, our laundry wash bags allow you to wash your delicates without worrying about damage in the washing machine or dryer. The fine mesh material allows soap and water to flow freely, ensuring thorough cleaning","All-in-One, One for You: Featuring 7 pieces in 6 distinct sizes and shapes, this laundry bag set offers a variety of options to suit your specific needs, making it a versatile solution for your daily cleaning tasks. The color-coded tips on each bag further enhance their functionality for organization","Beyond Just Laundry: Besides being ideal for delicate garments, these versatile bags excel at organizing luggage during travel. They''re perfect for storing various small items such as children''s toys, rubber balls, makeup, laundry accessories, clothespins, stuffed animals, and more","Warm Tips: ①Please note that to achieve better washing results, the capacity of clothes should not exceed 2/3 of the total capacity of each laundry bag. ②Remember to put the zipper under the elastic band before washing.","[Customer First, Services Foremost.]: Your satisfaction is our top priority, plz rest assured to purchase our products. If you are not satisfied with our products or have any questions, please feel free to contact us at any time, Let us remove any worry or hassle with our unique money back plus guarantee which means that if you are not totally satisfied with your product, we will refund you and you keep mesh laundry bags"]');
