INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B09961TCV4','huefull Genuine Jade Roller & Gua Sha Set for Face, Cooling & Firming Effect, Sculpting Tool for Jawline & Skin Care, Self-Care Gifts for Women & Men','huefull-genuine-jade-roller-gua-sha-set-for-face-cooling-fir-b09961tcv4','Symeno Select','Skincare Tools',6.99,'Benefits: Face roller helps reduce puffiness, refreshes skin, and provides a lifted, radiant appearance for your daily skincare routine。The perfect Mother''s Day gift. Face Roller: The face roller is smooth, durable, and squeak-free.Portable and easy to use，made from natural jade, it provides a cooling sensation that energizes the skin with every roll. Gua Sha: The Gua Sha tool is designed to contour and define your face, sculpting the jawline with its unique shape. It can be paired with facial oils or serums for a gentle massage, suitable for all skin types. Easy to clean: Both the face roller and Gua Sha tool are easy to clean with a wet towel before and after use, making maintenance simple. A great gift for women, perfect for birthdays or spa lovers. Gift Package: The set includes 1 Jade Roller and 1 Gua Sha Stone, beautifully packaged and ready for gifting. A thoughtful self-care gifts for women, wives, friends, or employees, perfect for birthdays, Mother''s Day, and special occasions','["https://m.media-amazon.com/images/I/61MOyEPAFYL._SL1500_.jpg","https://m.media-amazon.com/images/I/81OfWJAukRL._SL1500_.jpg","https://m.media-amazon.com/images/I/71msmfyVN4L._SL1500_.jpg","https://m.media-amazon.com/images/I/71tkuy8163L._SL1500_.jpg","https://m.media-amazon.com/images/I/71FB7CtZC7L._SL1500_.jpg","https://m.media-amazon.com/images/I/81Qd0LPMSiL._SL1500_.jpg","https://m.media-amazon.com/images/I/71CUGaQ3V9L._SL1500_.jpg","https://m.media-amazon.com/images/I/71DFjOBMLqL._SL1500_.jpg"]',