INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B085DMV7XD','Lamicall Bike Phone Holder, Motorcycle Mount - Motorcycle Phone Holder, Handlebar Cell Phone Cl E-Bike Scooter Phone Clip for 4.7-6.8" Smartphones, iPhone 17 Air Pro Max, 16 15 Plus Mothers Day','lamicall-bike-phone-holder-motorcycle-mount-motorcycle-phone-b085dmv7xd','Lamicall','Cycling & Urban Mobility',15.99,'Sturdy and Safe: A special shape of this motorcycle & bike phone holder grips each corner of your phone tightly. It ensures the safety of your cell phone attached to the bike handlebar even on a bumpy road. Phone clip must be locked by the red switch on the back so that phone doesn''t fall off while riding!. Shockproof Protection: This bicycle accessories - adjustable bike phone mount comes with silicone pads that keep your phone from scratches and vibration. The motorcycle phone mount holds your phone perfectly when cycling.. Wide Compatibility: This universal bike accessories cell phone holder suit for 4.7 to 6.8 inches with thickness up to 0.59“ (15mm, including phone case), like iPhone 17, iPhone Air, iPhone 17 Pro, iPhone 17 Pro Max, iPhone 16, iPhone 16 Plus, iPhone 16 Pro, iPhone 16 Pro Max, iPhone 15 Plus / Pro /Pro Max, iPhone 14 13 Pro Max, 12 Mini, Xs XR X 8 Plus 7 6s 6, Galaxy S24 23 22, Note 9, LG and other cell phones.. Adjustable Features: This motorcycle accessories easy to adjust the cellphone to horizontal or vertical screen. It is convenient to answer the phone, play music, GPS positioning during the riding.. Easy Installation: One hand operation motorcycle phone mount is easy to install without tool. The extra 4 silicone pads make your phone fit better with handlebar, can add or remove the silicone pad according to the diameter of handlebar. Suit well with various types of bicycles, motorcycles, stroller, shopping cart, electric scooter, electric bike, ebike, dirt bike. Note: Fit Handlebar diameter from 0.59 to 1.57" (15-40mm).. Note: Fit Handlebar diameter from 0.59 to 1.57" (15-40mm). Please measure the diameter of your handlebars before purchasing to see if this product will fit. Suit for phone from 4.7 to 6.8”. The maximum adaptable thickness of the phone is 0.59” (15mm, including phone case)','["https://m.media-amazon.com/images/I/711bZ97mpyL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/612vSK1V5NL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/714O1CNQcBL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71+XHIh8ExL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71hMKc-dmQL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71gyoz+0OeL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71ntSt1Ft5L._AC_SL1500_.jpg"]',4.6,66327,'hasdata','https://www.amazon.com/dp/B085DMV7XD',1778332713,1,NULL,'["Sturdy and Safe: A special shape of this motorcycle & bike phone holder grips each corner of your phone tightly. It ensures the safety of your cell phone attached to the bike handlebar even on a bumpy road. Phone clip must be locked by the red switch on the back so that phone doesn''t fall off while riding!","Shockproof Protection: This bicycle accessories - adjustable bike phone mount comes with silicone pads that keep your phone from scratches and vibration. The motorcycle phone mount holds your phone perfectly when cycling.","Wide Compatibility: This universal bike accessories cell phone holder suit for 4.7 to 6.8 inches with thickness up to 0.59“ (15mm, including phone case), like iPhone 17, iPhone Air, iPhone 17 Pro, iPhone 17 Pro Max, iPhone 16, iPhone 16 Plus, iPhone 16 Pro, iPhone 16 Pro Max, iPhone 15 Plus / Pro /Pro Max, iPhone 14 13 Pro Max, 12 Mini, Xs XR X 8 Plus 7 6s 6, Galaxy S24 23 22, Note 9, LG and other cell phones.","Adjustable Features: This motorcycle accessories easy to adjust the cellphone to horizontal or vertical screen. It is convenient to answer the phone, play music, GPS positioning during the riding.","Easy Installation: One hand operation motorcycle phone mount is easy to install without tool. The extra 4 silicone pads make your phone fit better with handlebar, can add or remove the silicone pad according to the diameter of handlebar. Suit well with various types of bicycles, motorcycles, stroller, shopping cart, electric scooter, electric bike, ebike, dirt bike. Note: Fit Handlebar diameter from 0.59 to 1.57\" (15-40mm).","Note: Fit Handlebar diameter from 0.59 to 1.57\" (15-40mm). Please measure the diameter of your handlebars before purchasing to see if this product will fit. Suit for phone from 4.7 to 6.8”. The maximum adaptable thickness of the phone is 0.59” (15mm, including phone case)"]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0BN551HR2','Lamicall Motorcycle Phone Mount Holder - [Camera Friendly] [1s Lock] Bike Phone Holder Handlebar Cl Bicycle Scooter Phone Clip, Gifts for iPhone 17, 16, 15 Pro Max, Galaxy S25 Ultra, 4.7-7" Phones','lamicall-motorcycle-phone-mount-holder-camera-friendly-1s-lo-b0bn551hr2','Lamicall','Cycling & Urban Mobility',16.99,'【 1s Lock & Release】NOTICE: The width of the phone clip can be adjusted. Turn the knob counterclockwise to enlarge the width of the phone clip, then turn the knob clockwise to grip your phone. Finally lock the safety lock up to secure your phone firmly. Once settled, you can enjoy the fast installation in the future, one hand to install and release.. 【 No Block Camera】 The motorcycle phone mount adopts half enclosure design, so it won''t block your cellphone''s camera. Support photo shooting and video recording in cycling, making it a great bike accessory when you want to record your journey.. 【 Quick Install Handlebar Clip】 The upgrade handlebar clip makes the installation easier. Press the button on handlebar clip to adjust the clip to fit the handlebar, no tools are needed. The handlebar clip is suitable for bike, bicycle, motorcycle, electric scooter, stroller, shopping cart, indoor bike, treadmill. Fit handlebar diameter: 0.59 - 1.57" ( 15 - 40mm).. 【 for 4.7-7" Phones】 This motorcycle phone holder can fits all 2.3 - 3.54" wide phones, such as iPhone 17, iPhone Air, iPhone 17 Pro, iPhone 17 Pro Max, iPhone 16 Pro Max, 15/ 14/ 13/ 12/ 11 Pro Max, Pro, Mini, iPhone 16/ 15/ 14 Plus, iPhone Xs Max, Xs, XR, X, iPhone SE, Galaxy S25 Ultra, S24 Ultra, S23 Ultra, S23+, S23, S22, S21, more. The max thickness the phone clip can holds is 0.59".. 【 360° Rotation & Sturdy】The bike cell phone mount comes with 360 degrees rotating ball, allows you to adjust your cellphone to the horizontal or vertical viewing angle during riding. The all-around rubber pads on phone clip protect your phone from scratching and slipping. High quality handlebar clip holds the bar tightly, keep your phone safe and steady on bump road.','["https://m.media-amazon.com/images/I/6104nsuFpWL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/71L3ZQPff-L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71+mqZjUeEL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71r40loRXxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61--RDnkhyL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71HCgQct3CL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71aAtl6jFrL._AC_SL1500_.jpg"]',4.6,10884,'hasdata','https://www.amazon.com/dp/B0BN551HR2',1778332757,1,NULL,'["【 1s Lock & Release】NOTICE: The width of the phone clip can be adjusted. Turn the knob counterclockwise to enlarge the width of the phone clip, then turn the knob clockwise to grip your phone. Finally lock the safety lock up to secure your phone firmly. Once settled, you can enjoy the fast installation in the future, one hand to install and release.","【 No Block Camera】 The motorcycle phone mount adopts half enclosure design, so it won''t block your cellphone''s camera. Support photo shooting and video recording in cycling, making it a great bike accessory when you want to record your journey.","【 Quick Install Handlebar Clip】 The upgrade handlebar clip makes the installation easier. Press the button on handlebar clip to adjust the clip to fit the handlebar, no tools are needed. The handlebar clip is suitable for bike, bicycle, motorcycle, electric scooter, stroller, shopping cart, indoor bike, treadmill. Fit handlebar diameter: 0.59 - 1.57\" ( 15 - 40mm).","【 for 4.7-7\" Phones】 This motorcycle phone holder can fits all 2.3 - 3.54\" wide phones, such as iPhone 17, iPhone Air, iPhone 17 Pro, iPhone 17 Pro Max, iPhone 16 Pro Max, 15/ 14/ 13/ 12/ 11 Pro Max, Pro, Mini, iPhone 16/ 15/ 14 Plus, iPhone Xs Max, Xs, XR, X, iPhone SE, Galaxy S25 Ultra, S24 Ultra, S23 Ultra, S23+, S23, S22, S21, more. The max thickness the phone clip can holds is 0.59\".","【 360° Rotation & Sturdy】The bike cell phone mount comes with 360 degrees rotating ball, allows you to adjust your cellphone to the horizontal or vertical viewing angle during riding. The all-around rubber pads on phone clip protect your phone from scratching and slipping. High quality handlebar clip holds the bar tightly, keep your phone safe and steady on bump road."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0CJTGQVKC','LISEN Bike Phone Holder, [Super Easy Install] Motorcycle Phone Mount Ebike Accessories Bicycle Handlebar Holder Mount Gift for Adults Kids Mountain Mini Bike Scooter Gear Accessories for iPhone Pixel','lisen-bike-phone-holder-super-easy-install-motorcycle-phone-b0cjtgqvkc','LISEN','Cycling & Urban Mobility',9.99,'[Ultra-Secure Hold] – LISEN bike phone holder mount keeps your phone firmly in place even on bumpy or high-speed rides. Bicycle cell phone mount with all-around grip secures each corner, while the upgraded locking mechanism ensures maximum stability and easy access.. [Fast & Easy Installation] – This motorcycle phone holder mount no tools or complicated parts needed. Built-in silicone design lets you mount and tighten in seconds—quick setup in just 5 seconds without loose pieces.. [Shockproof Silicone Protection] – Full silicone wrap with anti-slip cushions absorbs shocks and prevents scratches. Our ebike accessories protects both your phone and handlebar, even on rough or off-road rides.. [Wide Phone Compatibility] – The bike accessories fits most smartphones from 4.7" to 6.8" with thickness up to 20mm, including iPhone 17 Pro Max and Samsung Galaxy S26 Ultra.. [Wide Compatibility for Bikes & eBikes] – Fits 0.6–1.57" round handlebars on bicycles, motorcycles, scooters, mini bike, mountain bike and eBikes. Ebikes including popular models like Yozma IN10, X1 Spark, Lectric, Jasion, Ridstar, and more.. As a responsible company, LISEN operates sustainably to high environmental and social standards, working closely with suppliers. Includes 12-month support for peace of mind.','["https://m.media-amazon.com/images/I/716LElKeDlL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71w0FMrcVHL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71s9LF3Xv9L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71dOh-JtpgL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71jz2ybtvAL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61jPApCiNjL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51wfG3NHc+L._AC_.jpg"]',4.6,6493,'hasdata','https://www.amazon.com/dp/B0CJTGQVKC',1778332729,1,NULL,'["[Ultra-Secure Hold] – LISEN bike phone holder mount keeps your phone firmly in place even on bumpy or high-speed rides. Bicycle cell phone mount with all-around grip secures each corner, while the upgraded locking mechanism ensures maximum stability and easy access.","[Fast & Easy Installation] – This motorcycle phone holder mount no tools or complicated parts needed. Built-in silicone design lets you mount and tighten in seconds—quick setup in just 5 seconds without loose pieces.","[Shockproof Silicone Protection] – Full silicone wrap with anti-slip cushions absorbs shocks and prevents scratches. Our ebike accessories protects both your phone and handlebar, even on rough or off-road rides.","[Wide Phone Compatibility] – The bike accessories fits most smartphones from 4.7\" to 6.8\" with thickness up to 20mm, including iPhone 17 Pro Max and Samsung Galaxy S26 Ultra.","[Wide Compatibility for Bikes & eBikes] – Fits 0.6–1.57\" round handlebars on bicycles, motorcycles, scooters, mini bike, mountain bike and eBikes. Ebikes including popular models like Yozma IN10, X1 Spark, Lectric, Jasion, Ridstar, and more.","As a responsible company, LISEN operates sustainably to high environmental and social standards, working closely with suppliers. Includes 12-month support for peace of mind."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0CST346DW','JOYROOM Motorcycle Bike Phone Holder Mount - [Not Block Camera] Bicycle Phone Holder Handlebar Cell Phone Clamp - [Silicone Wrapped] Scooter Phone Holder for iPhone Samsung 4.7''''-7'''' Smartphones','joyroom-motorcycle-bike-phone-holder-mount-not-block-camera-b0cst346dw','JOYROOM','Cycling & Urban Mobility',15.99,'🚲【Never Fall Off】JOYROOM 2026 new upgrade phone holder for bike comes with heavy-duty silicone pads and bottom support, which keep your phone from scratches and vibration. The double-layer locks firmly hold your phone, and won''t slide even with severe bumps.. 🚲【Camera Friendly】Our motorcycle phone holder mount adopts a half enclosure design, which does not block the camera and side buttons. And not affect face recognition. You can take photos and videos to record your travel moments at any time.. 🚲【1s Quick Locked and Release】Support for one-hand operation, only take 1s to put on and take off the phone effortlessly. Adjust the width of the phone clip to fit your phone for the first time, you can enjoy the fast installation in the future.. 🚲【Fit for Different Handlebars】The extra 4 pieces of rubber gaskets, make your phone fit better with a handlebar, and add or remove the silicone pad according to the diameter of the handlebar. Suit well with various types of bicycles, motorcycles, strollers, electric scooters, shopping carts, indoor pelotons, ATVs, UTVs, etc.. 🚲【Compatible with 4.7-7" Mobile Phones】Our bike phone holder fits 4.7" - 7" phones, like iPhone iPhone 17 / iPhone 17 Air / iPhone 17 Pro / iPhone 17 Pro Max/16/15/14/ 13/ 12/ 11 Pro Max, Pro, iPhone Xs, iPhone XR, X, 8 Plus 7 6s 6, Galaxy S24 Ultra, S24+, S24, S23 Ultra, S23+, S22, S21, S22, S10, S8, Note 9, LG and more smartphone.. 🚲【Doing Responsibly and Sustainably】JOYROOM handlebar phone mount provides 12 months service, if you encounter any problems, please contact us and we will provide you with a satisfactory solution.','["https://m.media-amazon.com/images/I/71v+yjFQ-HL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71GyFzggjrL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71IEwXW3sAL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71N9GxqPqmL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71N-FbD1CSL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71fHxxxM4rL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71CnTosAVKL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71Rg-gBz4wL._AC_SL1500_.jpg"]',4.6,2014,'hasdata','https://www.amazon.com/dp/B0CST346DW',1778332738,1,NULL,'["🚲【Never Fall Off】JOYROOM 2026 new upgrade phone holder for bike comes with heavy-duty silicone pads and bottom support, which keep your phone from scratches and vibration. The double-layer locks firmly hold your phone, and won''t slide even with severe bumps.","🚲【Camera Friendly】Our motorcycle phone holder mount adopts a half enclosure design, which does not block the camera and side buttons. And not affect face recognition. You can take photos and videos to record your travel moments at any time.","🚲【1s Quick Locked and Release】Support for one-hand operation, only take 1s to put on and take off the phone effortlessly. Adjust the width of the phone clip to fit your phone for the first time, you can enjoy the fast installation in the future.","🚲【Fit for Different Handlebars】The extra 4 pieces of rubber gaskets, make your phone fit better with a handlebar, and add or remove the silicone pad according to the diameter of the handlebar. Suit well with various types of bicycles, motorcycles, strollers, electric scooters, shopping carts, indoor pelotons, ATVs, UTVs, etc.","🚲【Compatible with 4.7-7\" Mobile Phones】Our bike phone holder fits 4.7\" - 7\" phones, like iPhone iPhone 17 / iPhone 17 Air / iPhone 17 Pro / iPhone 17 Pro Max/16/15/14/ 13/ 12/ 11 Pro Max, Pro, iPhone Xs, iPhone XR, X, 8 Plus 7 6s 6, Galaxy S24 Ultra, S24+, S24, S23 Ultra, S23+, S22, S21, S22, S10, S8, Note 9, LG and more smartphone.","🚲【Doing Responsibly and Sustainably】JOYROOM handlebar phone mount provides 12 months service, if you encounter any problems, please contact us and we will provide you with a satisfactory solution."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0DRVBB48P','Lamicall Motorcycle Bike Phone Mount - [No Block Camera] [1s Lock] Bike Cell Phone Holder Cl Bicycle Scooter Handlebar Clip, Gifts for iPhone 17 16 15 14 Pro Max, Galaxy S25 Ultra, 4.7-7" Phones','lamicall-motorcycle-bike-phone-mount-no-block-camera-1s-lock-b0drvbb48p','Lamicall','Cycling & Urban Mobility',17.99,'【Record Your Bike Journey】 For photography purposes, the bike phone mount is designed not to cover the rear camera. Ensure you can take photos and videos while riding, making it a great bike accessory for recording or sharing your cycling journey.. 【1s Lock & Release】 NOTICE: The width of the phone clip can be adjusted. Turn the knob counterclockwise to enlarge the width of the phone clip, then turn the knob clockwise to grip your phone. Finally lock the safety lock up to secure your phone firmly. Once settled, you can enjoy the fast installation in the future, one hand to install and release.. 【Secure & Stable Grip】 The phone holder for bike features a reinforced clamp and silicone padding to prevent drops, even on bumpy roads. Ensures your device stays secure, whether you’re commuting, touring, or hitting off-road trails.. 【One-hand Operation】 No need to push, just put the phone in with one hand, lock the buckle and go. A truly easy-to-use motorcycle phone mount. And its 360° adjustable design lets you rotate your phone horizontally or vertically for perfect visibility.. 【for 4.7-7" Phones】 This bicycle phone holder securely fits 2.3 - 3.54" wide cellphones, such as iPhone 17 Pro Max, iPhone Air, 16/ 15/ 14/ 13/ 12 Pro Max, Mini, iPhone 16 Plus, iPhone Xs Max, Xs, XR, X, iPhone SE, Galaxy S25 Ultra, S24 Ultra, S23, S22, S21, more. The max thickness the phone clip can holds is 0.59". Fit handlebar diameter: 0.59 - 1.57" ( 15 - 40mm), making it ideal for motorcycle, bicycle, scooter, stroller, shopping cart, indoor bike, treadmill, golf cart.','["https://m.media-amazon.com/images/I/61yFsuVpLPL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/719IUNQ6R3L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71fGzfEmnpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71dwx8VGivL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61e03ngJGdL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61p00QJxACL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61DhFSIlsDL._AC_SL1500_.jpg"]',4.6,835,'hasdata','https://www.amazon.com/dp/B0DRVBB48P',1778332764,1,NULL,'["【Record Your Bike Journey】 For photography purposes, the bike phone mount is designed not to cover the rear camera. Ensure you can take photos and videos while riding, making it a great bike accessory for recording or sharing your cycling journey.","【1s Lock & Release】 NOTICE: The width of the phone clip can be adjusted. Turn the knob counterclockwise to enlarge the width of the phone clip, then turn the knob clockwise to grip your phone. Finally lock the safety lock up to secure your phone firmly. Once settled, you can enjoy the fast installation in the future, one hand to install and release.","【Secure & Stable Grip】 The phone holder for bike features a reinforced clamp and silicone padding to prevent drops, even on bumpy roads. Ensures your device stays secure, whether you’re commuting, touring, or hitting off-road trails.","【One-hand Operation】 No need to push, just put the phone in with one hand, lock the buckle and go. A truly easy-to-use motorcycle phone mount. And its 360° adjustable design lets you rotate your phone horizontally or vertically for perfect visibility.","【for 4.7-7\" Phones】 This bicycle phone holder securely fits 2.3 - 3.54\" wide cellphones, such as iPhone 17 Pro Max, iPhone Air, 16/ 15/ 14/ 13/ 12 Pro Max, Mini, iPhone 16 Plus, iPhone Xs Max, Xs, XR, X, iPhone SE, Galaxy S25 Ultra, S24 Ultra, S23, S22, S21, more. The max thickness the phone clip can holds is 0.59\". Fit handlebar diameter: 0.59 - 1.57\" ( 15 - 40mm), making it ideal for motorcycle, bicycle, scooter, stroller, shopping cart, indoor bike, treadmill, golf cart."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B09D8WK8XG','Detachable Bike Phone Holder, Universal Bicycle Motorcycle Cell Phone Mount, 360° Rotatable Adjustable Bike Phone Mount Compatible for 4" to 6.7" Smartphones','detachable-bike-phone-holder-universal-bicycle-motorcycle-ce-b09d8wk8xg','Deerfun','Cycling & Urban Mobility',7.99,'Detachable Design -- The detachable Deerfun bike&motorcycle phone mount allows you to remove the cell phone without having to disassemble the entire phone holder, making it easy to send and receive emails or texts, answer calls, take selfies, and more.. Tool-Free Installation -- Absolutely no tools are required for installation of our bike cell phone holder. Built-in silicone pad, just tighten the silicone buckle on the handlebar, no matter what the terrain, it will firmly grip your handlebar and stay stable without shaking, also easily removable.. Wide Compatibility -- Made of tough and stretchy silicone bands, this universal bike phone mount will securely fit almost any cell phone up to 4.0 inches wide! Holds iPhone 12, 11, X, iPhone XR, iPhone 8 | 8Plus, iPhone 7 | 7 Plus. Samsung Galaxy S7 | Galaxy S7 Edge, Galaxy S9, OnePlus 3, HTC 11.. Universal Handlebar Phone Mount -- With adjustable elastic silicone straps, fits all 18-35mm handlebars, suitable for bicycles, motorcycles, scooter handlebar, strollers, shopping carts, etc. Just tighten the silicone buckle on the handlebar, no matter what the terrain, it will firmly grip your handlebar and stay stable without shaking.. Adjustable Features -- Easy to adjust the cellphone to horizontal or vertical screen. It is convenient to answer the phone, play music, GPS positioning during the riding.','["https://m.media-amazon.com/images/I/713pu-rzUaL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71QrsMBK-xL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71s54acry5L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71UGT82eLKL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71BDH4XGcIL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71njjYdVcVL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/813-sCk10gL._AC_SL1500_.jpg"]',4.5,3705,'hasdata','https://www.amazon.com/dp/B09D8WK8XG',1778332773,1,NULL,'["Detachable Design -- The detachable Deerfun bike&motorcycle phone mount allows you to remove the cell phone without having to disassemble the entire phone holder, making it easy to send and receive emails or texts, answer calls, take selfies, and more.","Tool-Free Installation -- Absolutely no tools are required for installation of our bike cell phone holder. Built-in silicone pad, just tighten the silicone buckle on the handlebar, no matter what the terrain, it will firmly grip your handlebar and stay stable without shaking, also easily removable.","Wide Compatibility -- Made of tough and stretchy silicone bands, this universal bike phone mount will securely fit almost any cell phone up to 4.0 inches wide! Holds iPhone 12, 11, X, iPhone XR, iPhone 8 | 8Plus, iPhone 7 | 7 Plus. Samsung Galaxy S7 | Galaxy S7 Edge, Galaxy S9, OnePlus 3, HTC 11.","Universal Handlebar Phone Mount -- With adjustable elastic silicone straps, fits all 18-35mm handlebars, suitable for bicycles, motorcycles, scooter handlebar, strollers, shopping carts, etc. Just tighten the silicone buckle on the handlebar, no matter what the terrain, it will firmly grip your handlebar and stay stable without shaking.","Adjustable Features -- Easy to adjust the cellphone to horizontal or vertical screen. It is convenient to answer the phone, play music, GPS positioning during the riding."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FM6YMS12','24 PCS Silicone Baby Feeding Set, Baby Led Weaning Supplies Includes Suction Bowls and Divided Plates, Adjustable Silicone Bib, Spoons&forks, Training cup with straw (Green+Brown+Beige)','24-pcs-silicone-baby-feeding-set-baby-led-weaning-supplies-i-b0fm6yms12','JELLDJK','Baby Accessories',54.99,'24 pcs Silicone Baby Feeding Set : Our silicone baby feeding set includes 3 suction divided plate, 3 adjustable silicone bib, 3 suction bowls, 3 sets of silicone spoon and forks, 3 sets of wooden spoons and forks, 3 training cup with straw.. Safe & Certified Materials: These baby dishes are made from food-grade silicone, meeting the rigorous standards of CPSIA Children''s Product Approval. This set is not only free from harmful substances like BPA, Phthalates, and PVC but is meticulously crafted with non-toxic, baby-safe materials.. Easy Cleaning: Our baby bowls and suction plates feature a powerful suction base to minimize spills. The spoons and forks are easy to hold and grip, while the tall curved sidewalls of the suction bowl assist with scooping and self-feeding. The super soft and lightweight bib effectively catches food, and the suction plate features divided sections to keep food separated.Plus, The toddler feeding supplies set is dishwasher, microwave, and freezer safe for hassle-free cleaning.. Double Handle Design: these cute baby snack cups feature double handles with a frosted design, which can increase the friction between the baby''s fingers and the handle, allowing the baby to hold it firmly, helping them maintain the good habit of eating alone.. Perfect Baby Gift: This silicone baby feeding set is designed for new parents and make mealtime easier for kids. They prevent spills, encourage self-feeding, and make a great gift for any special occasion.','["https://m.media-amazon.com/images/I/61X-WoruLcL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71rpfVM0FVL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71YyFn9s09L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71qA3QYDOPL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61ybAUqjxmL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61h9H2swAQL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71fW9k2+QsL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/616zFsJYv5L._AC_SL1500_.jpg"]',4.4,76,'hasdata','https://www.amazon.com/dp/B0FM6YMS12',1778332796,1,NULL,'["24 pcs Silicone Baby Feeding Set : Our silicone baby feeding set includes 3 suction divided plate, 3 adjustable silicone bib, 3 suction bowls, 3 sets of silicone spoon and forks, 3 sets of wooden spoons and forks, 3 training cup with straw.","Safe & Certified Materials: These baby dishes are made from food-grade silicone, meeting the rigorous standards of CPSIA Children''s Product Approval. This set is not only free from harmful substances like BPA, Phthalates, and PVC but is meticulously crafted with non-toxic, baby-safe materials.","Easy Cleaning: Our baby bowls and suction plates feature a powerful suction base to minimize spills. The spoons and forks are easy to hold and grip, while the tall curved sidewalls of the suction bowl assist with scooping and self-feeding. The super soft and lightweight bib effectively catches food, and the suction plate features divided sections to keep food separated.Plus, The toddler feeding supplies set is dishwasher, microwave, and freezer safe for hassle-free cleaning.","Double Handle Design: these cute baby snack cups feature double handles with a frosted design, which can increase the friction between the baby''s fingers and the handle, allowing the baby to hold it firmly, helping them maintain the good habit of eating alone.","Perfect Baby Gift: This silicone baby feeding set is designed for new parents and make mealtime easier for kids. They prevent spills, encourage self-feeding, and make a great gift for any special occasion."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FM7N938B','Silicone Baby Feeding Set 9 Pcs, Spill-Proof Suction Plate, Bowl, Bib, Silicone spoon&forks, Wooden Spoons&forks, Training cup with straw and Sippy Cup, Baby Eating Utensils (Green)','silicone-baby-feeding-set-9-pcs-spill-proof-suction-plate-bo-b0fm7n938b','JELLDJK','Baby Accessories',17.95,'9 Piece Silicone Baby Feeding Set : Elevate your baby''s mealtime experience with our comprehensive 9-piece feeding set. Silicone baby feeding set includes 1 suction divided plate, 1 adjustable silicone bib, 1 suction bowl, 1 sets of silicone spoon and fork, 1 sets of wooden spoons and fork, 1 straw cup and 1 sippy cup.. Extra Strong Suction: Our suction bowls and divided plates feature an upgraded suction base that locks firmly onto smooth highchair trays and tabletops. The sectioned plate helps separate different foods, encouraging independent eating while preventing spills, drops, and messes on the floor.. Easy to Clean:Silicone Baby Feeding Set is very easy to clean, even with water rinsing can be washed clean, it is lightweight, waterproof, easy to dry, can be used over and over again for a long time without replacement. All parts suitable for refrigeration, these pieces save you time on cleaning and allow for more precious moments with your little one.. Adjustable Silicone Bib: Our silicone bib is designed with a deeper and sturdier pocket, making it highly effective in catching dropped food and easy to clean. The adjustable circular design is particularly gentle on your baby''s skin.. Perfect Gift for Growing Babies: Beautifully packaged and thoughtfully designed, this complete feeding set makes an ideal gift for baby showers, birthdays, Christmas, or any milestone.','["https://m.media-amazon.com/images/I/61R8MDahpnL._AC_SL1500_.jpg","https://m.media-am