INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0DP6YCBZS','Moonkie Silicone Baby Bibs Set of 3, BPA Free Waterproof Baby Bibs for Eating, Soft Adjustable Silicone Bibs for Babies 6-12 Months, Toddler Bibs with Large Pocket Food Catcher (Ether/Sage/Cream)','moonkie-silicone-baby-bibs-set-of-3-bpa-free-waterproof-baby-b0dp6ycbzs','Symeno Select','Baby Accessories',12.99,'100%silicone. Imported. 【2025 NAPPA Winner】Recognized with a 2025 National Parenting Product Award for its thoughtful design and safe materials. These silicone bibs also make practical baby shower gifts for boys and girls.. 【Food-Grade Silicone】Made of high-quality, food-grade silicone that is BPA-free and phthalate-free. As baby bibs for eating, they are soft on a baby’s skin and safe for everyday use.. 【Bigger and Sturdy Pocket】Designed with a 9 × 2 inch deep pocket that stays open and helps catch food or liquids during mealtime. These food bibs help keep the eating area more manageable.. 【Adjustable Closure】Features a soft, adjustable neckband that fits comfortably around babies and toddlers. These silicone bibs for toddlers are suitable for ages 3–36 months and work well for daily feeding routines.. 【Easy to Clean】Made of waterproof, stain-resistant silicone, these baby bibs can be rinsed or wiped with soapy water and are dishwasher safe for quick cleaning.','["https://m.media-amazon.com/images/I/61jrHBhMhkL._SL1500_.jpg","https://m.media-amazon.com/images/I/71IBuOddiZL._SL1500_.jpg","https://m.media-amazon.com/images/I/71M9KAZWujL._SL1500_.jpg","https://m.media-amazon.com/images/I/71DBmqMCFZL._SL1500_.jpg","https://m.media-amazon.com/images/I/717vKT-yA-L._SL1500_.jpg","https://m.media-amazon.com/images/I/61k3mbrQ2AL._SL1500_.jpg","https://m.media-amazon.com/images/I/719f7zJpPVL._SL1080_.jpg","https://m.media-amazon.com/images/I/815xw4hT9uL._SL1500_.jpg","https://m.media-amazon.com/images/I/91aA2eRrlAL._SL1500_.jpg"]',4.8,1149,'hasdata','https://www.amazon.com/dp/B0DP6YCBZS',1778332810,1,NULL,'["100%silicone","Imported","【2025 NAPPA Winner】Recognized with a 2025 National Parenting Product Award for its thoughtful design and safe materials. These silicone bibs also make practical baby shower gifts for boys and girls.","【Food-Grade Silicone】Made of high-quality, food-grade silicone that is BPA-free and phthalate-free. As baby bibs for eating, they are soft on a baby’s skin and safe for everyday use.","【Bigger and Sturdy Pocket】Designed with a 9 × 2 inch deep pocket that stays open and helps catch food or liquids during mealtime. These food bibs help keep the eating area more manageable.","【Adjustable Closure】Features a soft, adjustable neckband that fits comfortably around babies and toddlers. These silicone bibs for toddlers are suitable for ages 3–36 months and work well for daily feeding routines.","【Easy to Clean】Made of waterproof, stain-resistant silicone, these baby bibs can be rinsed or wiped with soapy water and are dishwasher safe for quick cleaning."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FPQ9ST93','Silicone Baby Feeding Set, 18PCS Baby Led Weaning Supplies, Eating Essentials Utensils with Suction Plate and Bowl, Adjustable Silicone Bib, for 6+ Months (Green+Brown)','silicone-baby-feeding-set-18pcs-baby-led-weaning-supplies-ea-b0fpq9st93','JELLDJK','Baby Accessories',27.06,'18 Pcs Silicone Baby Feeding Set','["https://m.media-amazon.com/images/I/61+uOBVOi8L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71F7ShlRZ-L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61RO8U+bfEL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71YyFn9s09L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71qA3QYDOPL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61ybAUqjxmL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61EO5oDvKnL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/616zFsJYv5L._AC_SL1500_.jpg"]',4.6,58,'hasdata','https://www.amazon.com/dp/B0FPQ9ST93',1778332851,1,NULL,'["Silicone Baby Feeding Set: the package comes with 18 sets of silicone baby feeding set in 2 different color, 9 pieces per set, and each set contains Suction Bowls and Divided Plates, Adjustable Silicone Bib, Silicone spoon&forks, Stainless Steel Spoons&forks, straw cup and sippy cup, helping your baby transition to self eating","Extra Strong Suction: Our suction bowls and divided plates feature an upgraded suction base that locks firmly onto smooth highchair trays and tabletops. The sectioned plate helps separate different foods, encouraging independent eating while preventing spills, drops, and messes on the floor.","Double Handle Design: these cute baby snack cups feature double handles with a frosted design, which can increase the friction between the baby''s fingers and the handle, allowing the baby to hold it firmly, helping them maintain the good habit of eating alone","Adjustable Design: The silicone bibs neck straps provide four adjustable different sizes, bibs feature rounded, built-in neck fasteners for a snug and comfy fit. Deep front pocket is perfect for catching food, keeping your baby and surrounding area clean.","Easy to Clean: these baby self eating supplies are easy to wash, and can be put into the dishwasher for easy cleaning, so that you no longer feel a headache from too much tableware, saving time and effort, In addition, they can withstand high temperatures, suitable for microwave use"]');
