INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0BQ8K62B5','Learning Resources Sensory Trio Fidget Tubes - Sensory Toys for Toddlers, Calming Kids Fidget Toys, Classroom Calm Down Corner Supplies, Special Needs Travel Fidgets, Preschool Quiet Time Items','learning-resources-sensory-trio-fidget-tubes-sensory-toys-fo-b0bq8k62b5','Symeno Select','Kids Toys & Learning',17.59,'Explore the sights, sounds, and textures of these flippable sensory fidget tubes! Kids build essential fine motor and sensory skills every time they play with the Sensory Trio Fidget Tubes from Learning Resources. Each tube engages a different sense through fun hands-on play-listen to falling beads as they tumble down the tube, watch the swirl of glitter to spot hidden smiley faces, or feel the weight of falling sand as it cascades from one end to the other. The sensory fun doesn''t stop there-features including a twist-and-click mechanism and fun grabbable textures ensure that kids stay engaged while building important developmental skills. Sized perfectly for little hands, these fidget tubes are ready for play at home or on the go-keep them in the playroom for breaks, or stash them in the car for on-the-road entertainment! Designed to help lower stress, provide calm after challenges, and regulate emotions, these sensory toys give kids the tools they need to self-regulate. Children across various ages enjoy these versatile tubes, from toddlers fascinated by the movements to older children who benefit from the calming input. Perfect for ages 3+ and a favorite among parents of children with sensory needs or those looking for engaging, screen-free activities.','["https://m.media-amazon.com/images/I/81lHfFkWm9L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81svUXWVi2L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81EEUq6IFVL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81jEG1NZ+8L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81qwuxyyM4L._AC_SL1500_.jpg"]',4.7,2579,'hasdata','https://www.amazon.com/dp/B0BQ8K62B5',1778332946,1,NULL,'["SENSORY DEVELOPMENT: Engages visual and tactile play with three motionfilled tubes featuring glitter, flowing sand, and cascading beads that invite causeandeffect exploration and handson activity","DURABLE CONSTRUCTION: Built with sturdy materials that hold up to drops and energetic play, offering longlasting fidget tubes for kids, toddlers, and preschoolers to explore again and again","CALMING EFFECT - Creates a perfect tool for helping children self-regulate emotions and focus attention, making it ideal for calm-down corners, travel distractions, or transitional moments","VERSATILE APPEAL - Captivates children across age ranges from toddlers to school-age, with many parents noting these fidget tubes engage children with special needs and neurotypical children alike","PORTABLE ENTERTAINMENT: Perfectly sized tubes fit comfortably in small hands and travel bags, making them easy to take along for restaurant waits, car rides, classrooms, or onthego activities"]');
