INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B09MTK9K3F','10 Pack Brown Gift Boxes, 9.45x6.5x4 Inches Kraft Paper Boxes with Lids for Valentine''s, Birthday party, Wedding, Cupcake Boxes, Easy Assemble Bridesmaids Proposal Boxes, With 66ft Twine','10-pack-brown-gift-boxes-945x65x4-inches-kraft-paper-boxes-w-b09mtk9k3f','Bssay','Gift Boxes & Packaging',9.99,'【 9.45 x 6.5 x 4" Brown Gift Boxes】Our brown gift boxes are made of high quality kraft paper with a rustic and beautiful appearance. The gift box is the perfect size and shape, perfect for mugs, body soap, trinkets, perfume, makeup, cupcakes or artisan cookies and more. NOTE: You will get 10 packs of 9.45x6.5x4 gift boxes and 2 bundles of twine (66ft total).. 【Assemble in Seconds】These gift boxes are flat packed, pre-folded and easy to assemble. When you don''t need to use it, you can return the box to a flat shape for easy storage. It is completely reusable and recyclable.. 【Share Your Love】 Add some atmosphere to the festival, you could embellish the paper gift boxes with metallic wire-edged ribbon, gift twine, or decoupage paper! Try to decorate gift boxes with specific ink stamps or stencil on a beautiful design for Valentine''s, Christmas, birthday party.. 【Food grade paper gift box】These paper gift boxes are made of high quality food grade paper and have 2 times the load carrying capacity of other gift boxes. Our boxes are safe, non-toxic and tasteless. You can use these big gift boxes to store cakes, breads, cupcakes, pastries and other baked goods.. 【Thicken Gift Boxes】 9.45x6.5x4 inches brown gift boxes could be used for bridesmaid proposal gifts, Valentine''s gifts and Christmas gifts, giving surprise in your life. if there''s anything make you unhappy or unsatisfied, please do contact us without any hesitation.','["https://m.media-amazon.co