INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0CNLVV6WT','UnicoPak 18 Pack 9x6x4 Gift Boxes Bulk Brown Kraft Gift Boxes with Lids for Presents for Gifts Birthday Wedding Bridesmaid Proposal Valentines Christmas','unicopak-18-pack-9x6x4-gift-boxes-bulk-brown-kraft-gift-boxe-b0cnlvv6wt','UnicoPak','Gift Boxes & Packaging',17.99,'18pcs Kraft Boxes Value Pack - Including 18 Brown boxes, each gift box measures 9x6x4 inches, has plenty of space for gifts, perfect size for birthday gifts wedding gifts party gifts bridesmaid gifts groomsmen gifts Valentine''s Day gifts Christmas gifts. High-quality Materials Made In The USA - These large gift boxes are well made with kraft cardboard paper, sturdy and recyclable, especially food safe, it can also be used as food boxes bakery boxes cookie boxes. The reinforced bottom can hold over 3 Lbs without worrying about coming off and don''t need to tape the gift box bottom. Pop-up Design Quick Assembly - Easy to assemble in few seconds with the pop-up structure, has done half the work for you. No need to waste your time on assembling these brown gift boxes with lids. Fit Any Gift Giving Moments - Just a little decoration with markers, stickers, ribbon or wrapping paper, it would become stunning boxes for wrapping gifts, perfect for any occasions like birthday, wedding, baby shower, bridesmaid proposal, holidays. Quality Guaranteed By UnicoPak - The perfect mate for your gifts! UnicoPak is committed to producing high-quality eco-friendly boxes and bags for everyone, hoping our gift boxes can bring you surprises and joy. For any issues, welcome to contact us via email','["https://m.media-amazon.com/images/I/71WdJ079+lL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71f+UX0+gIL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71PWr+JU-NL._AC_SL1500_.jpg","https://m