INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B095BMF9XY','Stockroom Plus Square Nesting Boxes With Lids - Kraft Brown, Paperboard, 4-Pack, 6.5-3.5 In - Cardboard Nesting Gift Boxes for Presents & Party Favors','stockroom-plus-square-nesting-boxes-with-lids-kraft-brown-pa-b095bmf9xy','Stockroom Plus','Gift Boxes & Packaging',13.49,'Elegant Gift Presentation: Elevate your gift-giving with Stockroom Plus Square Nesting Boxes with Lids, tailored for those who prize elegance. These square gift boxes with lids offer a refined and versatile solution for any occasion. Efficient Storage Solution: Maximize space with these nesting boxes gift set, designed to fit compactly within each other. Ideal for organizing desks, drawers, or household items when not being used for presents. Durable and Stylish: Crafted from sturdy paperboard, these cardboard nesting gift boxes with lids maintain an elegant appearance. Perfect for securely housing gifts while adding a sophisticated touch to your presentation. Versatile Size Options: This set includes four sizes of square gift boxes with lids, ranging from 6.5 inches to 3.5 inches. Suitable for a variety of gifting needs, they are perfect for events like weddings and birthdays. Decorative and Functional: Enhance your decor with these decorative gift boxes, perfect for wrapping presents or organizing small items. Their lightweight construction ensures easy handling and adds a modern touch to any event','["https://m.media-amazon.com/images/I/51+Tra+tgnL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71puYSni1dL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/41d+91MQ6QL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51D2yFmj0xL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61HQKNylAxL._AC_SL1500_.jpg"]',4.4,570,'hasdata','https://www.amazon.com/dp/B095BMF9XY',1778333124,1,NULL,'["Elegant Gift Presentation: Elevate your gift-giving with Stockroom Plus Square Nesting Boxes with Lids, tailored for those who prize elegance. These square gift boxes with lids offer a refined and versatile solution for any occasion","Efficient Storage Solution: Maximize space with these nesting boxes gift set, designed to fit compactly within each other. Ideal for organizing desks, drawers, or household items when not being used for presents","Durable and Stylish: Crafted from sturdy paperboard, these cardboard nesting gift boxes with lids maintain an elegant appearance. Perfect for securely housing gifts while adding a sophisticated touch to your presentation","Versatile Size Options: This set includes four sizes of square gift boxes with lids, ranging from 6.5 inches to 3.5 inches. Suitable for a variety of gifting needs, they are perfect for events like weddings and birthdays","Decorative and Functional: Enhance your decor with these decorative gift boxes, perfect for wrapping presents or organizing small items. Their lightweight construction ensures easy handling and adds a modern touch to any event"]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FNWJS79G','Fullive 1 1/2 Inch Champagne Gold Ribbon, 30 Yards Satin Ribbon, Polyester Satin Ribbons for Wedding Xmas Tree Graduate New Years Decorations DIY Bows Bouquet Gift Wrapping Christmas Favors','fullive-1-12-inch-champagne-gold-ribbon-30-yards-satin-ribbo-b0fnwjs79g','FULLIVE','Gift Boxes & Packaging',6.99,'What''s Inside: Our new year''s ribbon collection includes a stunning gold wired ribbon that brings a luxurious feel to any celebration. Its vibrant color and texture elevate the ambiance of your gatherings, making every occasion visually delightful. Let your creativity shine as you craft unique designs for your new year celebrations and Christmas party. Perfectly Crafted: Measuring 1.57 inches in width and featuring a generous 30-yard length, our gold Christmas ribbon is designed to fulfill all your party decoration needs. With its fine single-sided finish and glossy surface, this ribbon remains intact, allowing for easy cutting to your desired length. Create beautiful accents for your new year festivities effortlessly. Premium Quality: Made from high-quality polyester fibers, our satin ribbon 1 1/2 inch option is soft, solid, and resistant to fading and wear. This elegant ribbon not only enhances your flower bouquets but also adds a touch of sophistication to your new year''s decorations. Enjoy the wrinkle-resistant and foldable nature of this versatile ribbon. Versatile Usage: Perfect for various activities, our ribbon for hair and crafting can be used for DIY projects, gift wrapping for new year gifts, festive bows, and more. Whether it''s for creating stunning anniversary balloon decorations or adding flair to your new year parties, this ribbon has got you covered. Convenient Storage: Each roll of our gift ribbon comes neatly wound on a sturdy plastic core and packaged in a protective blister pack, ensuring it stays clean and ready for use. Easily twist or tie the ribbons into shapes that suit your new year''s theme, simplifying your decoration process while enhancing your event''s charm','["https://m.media-amazon.com/images/I/813EZgjhy0L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/718CBveBXoL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/8138IxhVvuL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81-VSebV5YL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71sEHOqUzQL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81+jRusvF9L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71jyV1vio9L._AC_SL1500_.jpg"]',4.6,657,'hasdata','https://www.amazon.com/dp/B0FNWJS79G',1778333147,1,NULL,'["What''s Inside: Our new year''s ribbon collection includes a stunning gold wired ribbon that brings a luxurious feel to any celebration. Its vibrant color and texture elevate the ambiance of your gatherings, making every occasion visually delightful. Let your creativity shine as you craft unique designs for your new year celebrations and Christmas party","Perfectly Crafted: Measuring 1.57 inches in width and featuring a generous 30-yard length, our gold Christmas ribbon is designed to fulfill all your party decoration needs. With its fine single-sided finish and glossy surface, this ribbon remains intact, allowing for easy cutting to your desired length. Create beautiful accents for your new year festivities effortlessly","Premium Quality: Made from high-quality polyester fibers, our satin ribbon 1 1/2 inch option is soft, solid, and resistant to fading and wear. This elegant ribbon not only enhances your flower bouquets but also adds a touch of sophistication to your new year''s decorations. Enjoy the wrinkle-resistant and foldable nature of this versatile ribbon","Versatile Usage: Perfect for various activities, our ribbon for hair and crafting can be used for DIY projects, gift wrapping for new year gifts, festive bows, and more. Whether it''s for creating stunning anniversary balloon decorations or adding flair to your new year parties, this ribbon has got you covered","Convenient Storage: Each roll of our gift ribbon comes neatly wound on a sturdy plastic core and packaged in a protective blister pack, ensuring it stays clean and ready for use. Easily twist or tie the ribbons into shapes that suit your new year''s theme, simplifying your decoration process while enhancing your event''s charm"]');
