INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B08NXF43DB','MEEDEE 3/8 Inch Satin Ribbon Set – 10 Rolls Rainbow Double Face Ribbon for Gift Wrapping, 5 Yards Each (Total 50 Yards), Decorative Ribbon for Presents & Party Favors','meedee-38-inch-satin-ribbon-set-10-rolls-rainbow-double-face-b08nxf43db','MEEDEE','Gift Boxes & Packaging',7.99,'3/8 Inch Width – Ideal Size for Gift Wrapping. Each roll measures 3/8 inch wide and 5 yards long. The perfect thin satin ribbon size for wrapping small gift boxes, favor bags, party treats and decorative bows.. High quality satin ribbon set: These satin ribbon are washable 100% polyester fabric smooth surface ribbons that won''t shrink or fade, perfect for both crafts and sewing projects. Both sides of our ribbons are shiny and luxurious to the touch and being double faced means no matter how you use or tie them, they will look gorgeous.. Rainbow Shades: Enjoy 10 vibrant colors, including red, hot pink, orange, pink, yellow, apple green, green, blue, royal blue, and purple. With this classic rainbow theme, you''ll have enough ribbon for any occasion: rainbow pride day party decoration, wedding events, baby shower, birthday parties, bouquet wraps, or gift wrapping projects!. Well Packaged: Our ribbons are neatly packed on plastic spools and sealed in plastic bags, ensuring convenience and preventing dirt. The multicolored solid fabric ribbons feature stitched edges, offering a beautiful and shiny finish on both sides. These ribbons are versatile and can be used for various purposes, including branding your product packaging, creating mini hair bows, decorating cake pops, embellishing wedding bouquets, designing wedding invitations, and enhancing holiday decor.. Wide Application: Our beautiful, soft, and elegant satin ribbons have a wide range of uses, making them perfect for decorating clothes, costumes, and accessories. They are an excellent choice for birthday banners, gift baskets, and can be used to craft garlands, and decorate bottles. Additionally, these ribbons are suitable for card making, scrapbooking, and accenting DIY jewelry. With their versatility, you''ll discover endless creative possibilities to adorn any event with style.','["https://m.media-amazon.com/images/I/71J+MO6Ua+L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/712omcgMORL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/710IOHCKlLL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71dO13xMReL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/815fx1m1IYL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/712D-xJqNqL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71VAJ2RFTFL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71uEP3ClbWL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71xuA3o4dkL._AC_SL1500_.jpg"]',4.7,3034,'hasdata','https://www.amazon.com/dp/B08NXF43DB',1778333170,1,NULL,'["3/8 Inch Width – Ideal Size for Gift Wrapping. Each roll measures 3/8 inch wide and 5 yards long. The perfect thin satin ribbon size for wrapping small gift boxes, favor bags, party treats and decorative bows.","High quality satin ribbon set: These satin ribbon are washable 100% polyester fabric smooth surface ribbons that won''t shrink or fade, perfect for both crafts and sewing projects. Both sides of our ribbons are shiny and luxurious to the touch and being double faced means no matter how you use or tie them, they will look gorgeous.","Rainbow Shades: Enjoy 10 vibrant colors, including red, hot pink, orange, pink, yellow, apple green, green, blue, royal blue, and purple. With this classic rainbow theme, you''ll have enough ribbon for any occasion: rainbow pride day party decoration, wedding events, baby shower, birthday parties, bouquet wraps, or gift wrapping projects!","Well Packaged: Our ribbons are neatly packed on plastic spools and sealed in plastic bags, ensuring convenience and preventing dirt. The multicolored solid fabric ribbons feature stitched edges, offering a beautiful and shiny finish on both sides. These ribbons are versatile and can be used for various purposes, including branding your product packaging, creating mini hair bows, decorating cake pops, embellishing wedding bouquets, designing wedding invitations, and enhancing holiday decor.","Wide Application: Our beautiful, soft, and elegant satin ribbons have a wide range of uses, making them perfect for decorating clothes, costumes, and accessories. They are an excellent choice for birthday banners, gift baskets, and can be used to craft garlands, and decorate bottles. Additionally, these ribbons are suitable for card making, scrapbooking, and accenting DIY jewelry. With their versatility, you''ll discover endless creative possibilities to adorn any event with style."]');
