INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0D4TX9TBL','&And Per Se Dotted Notebook, A5 Hardcover with Journal Dotted Pages, Journal Stencils & Pen, 176 Numbered Pages for Beginners Women Men (Green)','and-per-se-dotted-notebook-a5-hardcover-with-journal-dotted-b0d4tx9tbl','&And Per Se','Stationery & Journaling',11.98,'【The Complete Dotted Journal Kit – Everything You Need to Begin】Step into the world of dot grid journaling with confidence. This all-in-one dotted journal kit includes a premium A5 dotted notebook, 2 durable sheets of stencils, and a smooth-writing fineliner pen. No more searching for extras—open it and start your journaling, sketching, habit tracking, or daily diary today.. 【176 Numbered Pages, 100gsm Thick Paper – Ideal for Dot Grid Journal】Crafted with 176 numbered pages of 100gsm premium paper, this dotted notebook stands up to your favorite pens. The thick, bleed-resistant paper works beautifully with fineliners, gel pens — no ghosting, no bleed-through. Perfect for creating clean spreads in your dot grid journal.. 【180° Lay-Flat Design – Comfortable Writing Anywhere】The durable leather hardcover opens completely flat, providing a stable writing surface whether you''re at a desk, on a couch, or commuting. The smooth-lay design makes it easy to sketch, take notes, or dotted journal without struggling to hold pages open—so you never miss a moment of inspiration.. 【2 Reusable Journal Stencils – Create Like a Pro, Even as a Beginner】Worried about drawing straight lines or perfect circles? The included flexible and durable stencils make it effortless. Design custom layouts, frames, and icons in minutes — no artistic skills required. Whether you''re building a habit tracker or a monthly calendar, these stencils turn your dotted journal into a professional-looking planner.. 【A Thoughtful Gift for Every Journal Lover】This dotted journal kit is an ideal present for students, artists, planners, or anyone who loves to stay organized. Perfect for birthdays, holidays, back-to-school, or just because. Available in multiple colors to suit every style—give the gift of creativity with a complete dotted journal setup.','["https://m.media-amazon.com/images/I/91yluWD1s7L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/616y9pPeeHL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81gnMk5rt3L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71ohTF1X2bL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71tCXbaN24L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81yENd5hP8L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81YOPDYB9JL._AC_SL1500_.jpg"]',4.6,243,'hasdata','https://www.amazon.com/dp/B0D4TX9TBL',1778333288,1,NULL,'["【The Complete Dotted Journal Kit – Everything You Need to Begin】Step into the world of dot grid journaling with confidence. This all-in-one dotted journal kit includes a premium A5 dotted notebook, 2 durable sheets of stencils, and a smooth-writing fineliner pen. No more searching for extras—open it and start your journaling, sketching, habit tracking, or daily diary today.","【176 Numbered Pages, 100gsm Thick Paper – Ideal for Dot Grid Journal】Crafted with 176 numbered pages of 100gsm premium paper, this dotted notebook stands up to your favorite pens. The thick, bleed-resistant paper works beautifully with fineliners, gel pens — no ghosting, no bleed-through. Perfect for creating clean spreads in your dot grid journal.","【180° Lay-Flat Design – Comfortable Writing Anywhere】The durable leather hardcover opens completely flat, providing a stable writing surface whether you''re at a desk, on a couch, or commuting. The smooth-lay design makes it easy to sketch, take notes, or dotted journal without struggling to hold pages open—so you never miss a moment of inspiration.","【2 Reusable Journal Stencils – Create Like a Pro, Even as a Beginner】Worried about drawing straight lines or perfect circles? The included flexible and durable stencils make it effortless. Design custom layouts, frames, and icons in minutes — no artistic skills required. Whether you''re building a habit tracker or a monthly calendar, these stencils turn your dotted journal into a professional-looking planner.","【A Thoughtful Gift for Every Journal Lover】This dotted journal kit is an ideal present for students, artists, planners, or anyone who loves to stay organized. Perfect for birthdays, holidays, back-to-school, or just because. Available in multiple colors to suit every style—give the gift of creativity with a complete dotted journal setup."]');
