INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B01IWBF49K','Growoya Garden OYA Medium Watering Pot Plant Irrigation System Sustainable Traditional Olla Watering Smart Underground Watering Available for Garden Beds Raised Beds and Grow Bags','growoya-garden-oya-medium-watering-pot-plant-irrigation-syst-b01iwbf49k','Symeno Select','Plant Care',54.95,'Revolutionize Your Garden with the Oya Watering Pot from GrowOya. Also known as an Olla, our Watering Pot is crafted from a unique and porous clay formula, your ultimate trick saving upto 70% on garden watering.. Smart Watering, Happy Plants! Bury the Oya Watering Pot among your plants and witness a sustainable gardening miracle. The roots of your plants will gravitate towards the water source, attaching themselves to the pots exterior.. Save Time Watering. Instead of daily watering, water just every 5-7 days with the Oya Watering Pot. Tired of the daily surface watering routine? The irrigation method changes the game.. No more wasteful watering – your plants take just what they need. Initially, surface water for the first couple of weeks, then let the Oya Watering Pot do thRefill every 5-7 days or when the water level is low. Embrace a lush, thriving garden with minimal effort and maximum automatic watering efficiency.e work for you. Available in three sizes, 5” x 7,, 7 x 10, 10 x 13. Ideal for raised beds, grow bags, hanging planters, and in-ground gardening. Compatible with all soil types, its durable design resists root damage and is easy to clean with a wire brush and vinegar solution. While roots naturally seek water, placing the pot at the center of plant clusters ensures optimal hydration.','["https://m.media-amazon.com/images/I/61SFQ+eR1VL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/9153Xr+92YL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/6129oOspN8L._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61mxjQ6W7HL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/71R44mHQ4HL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/71H6ekGpu1L._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/51lmABcIzsL._AC_.jpg","https://m.media-amazon.com/images/I/618sSkrmyGL._AC_SL1000_.jpg"]',4.6,201,'hasdata','https://www.amazon.com/dp/B01IWBF49K',1778333521,1,NULL,'["Revolutionize Your Garden with the Oya Watering Pot from GrowOya. Also known as an Olla, our Watering Pot is crafted from a unique and porous clay formula, your ultimate trick saving upto 70% on garden watering.","Smart Watering, Happy Plants! Bury the Oya Watering Pot among your plants and witness a sustainable gardening miracle. The roots of your plants will gravitate towards the water source, attaching themselves to the pots exterior.","Save Time Watering. Instead of daily watering, water just every 5-7 days with the Oya Watering Pot. Tired of the daily surface watering routine? The irrigation method changes the game.","No more wasteful watering – your plants take just what they need. Initially, surface water for the first couple of weeks, then let the Oya Watering Pot do thRefill every 5-7 days or when the water level is low. Embrace a lush, thriving garden with minimal effort and maximum automatic watering efficiency.e work for you. Available in three sizes, 5” x 7,, 7 x 10, 10 x 13","Ideal for raised beds, grow bags, hanging planters, and in-ground gardening. Compatible with all soil types, its durable design resists root damage and is easy to clean with a wire brush and vinegar solution. While roots naturally seek water, placing the pot at the center of plant clusters ensures optimal hydration."]');
