INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0D8PT296S','Back to the Roots Self-Watering Terracotta Olla Pot (Pack of 3), 700mL Provides 1 Week of Precision Watering','back-to-the-roots-self-watering-terracotta-olla-pot-pack-of-b0d8pt296s','Symeno Select','Plant Care',29.82,'The Olla (pronounced “oy-ya”) is an ancient gardening tool that has been used for over 4,000 years by desert farmers to help grow plants in dry, tough climates. This Low-Fired Clay Pot creates a microporous surface that slowly releases water through osmosis as your plants need it. Now, you can bring that same ancient technology into your home and experience worry-free watering — indoors or out! What are you waiting for? Let’s grow!','["https://m.media-amazon.com/images/I/81ylSlJA53L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71-N-RR1t4L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/91IS3LEZlsL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81dASl3lETL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81kP9sjlpTL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/91itcpNhTxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/91yXV2R7ZcL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71hI31+6VvL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81nwiqGNJBL._AC_SL1500_.jpg"]',4.7,895,'hasdata','https://www.amazon.com/dp/B0D8PT296S',1778333567,1,NULL,'["18 Diameter Coverage to support 2 large plants","Weather-Proof Rubber Stopper prevents evaporation","700 mL Capacity covers you during those long weekend getaways","100% GUARANTEED TO GROW: If you are not satisfied or have any issues, just shoot us a note and our dedicated customer support team will make sure we get you growing or send you a refund/replacement.","GROWONEGIVEONE — Help us make gardening a part of every school curriculum. Share a photo of your growing planter & we’ll donate a Grow Kit & STEM elementary school curriculum to a classroom of your choice"]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B09DCD1T4K','Phoenix Vine 4 Inch Self Watering Plants Pot, Design Terracotta Pot for Plants, Indoor Cylinder Terra Cotta Planter with Glass Vase, Set of 1, 51-A-E-1','phoenix-vine-4-inch-self-watering-plants-pot-design-terracot-b09dcd1t4k','Symeno Select','Plant Care',15.29,'Self-watering System: The terracotta pot is unglazed, just fill the glass container with water to ensure plants will absorb only what they need through the terracotta pot walls.. Terracotta + Glass: Elegant modern design self watering plants pot with ingenious natural breathable terra cotta material and clear glass container. See the water surplus just from a glance.. Dimensions: 4.8" Outer Diameter ( 3.7" Inner Diameter) × 4.6" Height. Please see the dimension image for details.. Low Maintenance: Add water to the glass container (approximately 1/3 fill) and your plants can be well cared for a week or two when you leave for a business trip or vacation.. Hassle-Free Replacement or Refund: Extremely well-designed package to prevent damage. If still any damage or issues, please feel free to reach out for a quick and satisfying hassle-free resolution.','["https://m.media-amazon.com/images/I/61yeGpnpKuL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81p6NnQtlHL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61jD4zcAT6L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71hhxY+pZYL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/91B-f7Am5rL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71w9E0e2P-L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81UIGfEPCUL._AC_SL1500_.jpg"]',4.5,490,'hasdata','https://www.amazon.com/dp/B09DCD1T4K',1778333596,1,NULL,'["Self-watering System: The terracotta pot is unglazed, just fill the glass container with water to ensure plants will absorb only what they need through the terracotta pot walls.","Terracotta + Glass: Elegant modern design self watering plants pot with ingenious natural breathable terra cotta material and clear glass container. See the water surplus just from a glance.","Dimensions: 4.8\" Outer Diameter ( 3.7\" Inner Diameter) × 4.6\" Height. Please see the dimension image for details.","Low Maintenance: Add water to the glass container (approximately 1/3 fill) and your plants can be well cared for a week or two when you leave for a business trip or vacation.","Hassle-Free Replacement or Refund: Extremely well-designed package to prevent damage. If still any damage or issues, please feel free to reach out for a quick and satisfying hassle-free resolution."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FNDNDFDJ','GUGUGO Self Watering Pot for Indoor Plants, 6 Inch Self-Watering Terracotta Plant Pots, Terracotta Planters with Clear Reservoir, Terra Cotta Flower Pots Planters, Large Modern Office Home Décor','gugugo-self-watering-pot-for-indoor-plants-6-inch-self-water-b0fndndfdj','Symeno Select','Plant Care',19.99,'Effortless Self-Watering System: This terracotta self watering pot uses high-quality porous clay that naturally absorbs water through its walls. Simply add water to the bottom reservoir, and the terracotta plant pot keeps your soil moist by drawing water upward—no need for daily watering. A great choice among self watering pots for indoor plants that makes plant care easier than ever.. Plant Care Made Easy While You’re Away: Fill the clear reservoir before weekend getaways or business trips. Your pothos, spider plants, or orchids will stay happy in these self watering terracotta pots for indoor plants while you''re away – no more asking neighbors to babysit your greenery! This easy plant self watering pot keeps your indoor oasis thriving with minimal effort.. Perfect Size for Any Space: The diameter of this 6 inch self watering pot is 6 inches, and the height is 5.4 inches—ideal for windowsills, desks, and bookshelves. Big enough for most houseplants like lucky bamboo or ferns, yet compact enough for studio apartments. Whether you need terracotta planters for indoor plants or a small accent for your workspace, it blends beautifully anywhere.. Convenient Side Refill Port: Our planter’s clever side-opening design lets you refill water without moving the pot. Just peek through the clear base to check levels—no messy spills or overwatering. This self watering terracotta pot offers a smart, clean solution that keeps your plants and furniture looking their perfect.. Rustic Elegance with Modern Touch: Combining timeless charm with functionality, these terracotta pots feature rustic clay warmth and a sleek acrylic base. Perfect for modern, minimalist, or farmhouse interiors, this terracotta self watering planter doubles as decor art while keeping your plants healthy and hydrated.. Healthy Roots, Happy Plants: Each large self watering planter includes a pack of lightweight clay pebbles that create a breathable barrier between roots and water. This helps prevent root rot and allows plants to drink at their own pace. Even your moody fiddle leaf fig will flourish in these self watering pots for outdoor plants or indoor settings alike.. Smart Design for Strong Growth: The upper terracotta section provides ample room for soil and roots, while the lower section maintains gentle water contact. This balance promotes healthy root systems and prevents overwatering. The large terracotta planter structure ensures both beauty and functionality for all your houseplants.. Stylish and Thoughtful Gift Idea: Featuring a unique blend of terracotta warmth and modern clarity, this self watering terracotta pot fits effortlessly into both indoor and outdoor spaces. Its elegant, practical design makes it a thoughtful gift for birthdays, holidays, or housewarmings. A must-have for fans of terracotta self watering pots for indoor plants and plant lovers of all kinds.','["https://m.media-amazon.com/images/I/7172KptWioL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81W4BZkQ0YL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71xm0XaNb7L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71YRUXzJA6L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71wWydZV51L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71vhXU351bL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71XyhDLHx2L._AC_SL1500_.jpg"]',3.7,4,'hasdata','https://www.amazon.com/dp/B0FNDNDFDJ',1778333603,1,NULL,'["Effortless Self-Watering System: This terra