INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0CG4HJ2SK','Glass Plant Mister - 6.5" Green Glass Water Spray Bottle with Gold Top Pump, Small Plant Sprayer for Indoor/Outdoor House Plants (Gray+Bronze)','glass-plant-mister-65-green-glass-water-spray-bottle-with-go-b0cg4hj2sk','Aebor','Plant Care',7.99,'The Glass Plant Mister Spray Bottle! --These lovely spray bottles provide you with the perfect decorative accent to place next to your potted plants on your patio, deck, or windowsill. --This glass misting bottle with perfume to spray a fine mist of your favorite scent on yourself or around your house. Specification: Color:Color:Gray + Bronze Capacity: 7 Oz. Size: 6.5" Tall:3.15" Diameter Material: Plastic Painted Metallic (Top Pump) + Glass (Bottle) Package includes: -1 x Small Glass Spray Bottle -1 x Top Pump Note: 1.Please allow 0-1cm error due to manual measurement. pls make sure you do not mind before you bid. 2.Due to the difference between different monitors, the picture may not reflect the actual color of the item. Thank you!','["https://m.media-amazon.com/images/I/613HXw0+CNL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61rtq4XB13L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61XS8UIW7OL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71jAOLjdnqL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71hT4sd8TyL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71myZ+4WnoL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61Zu8UgDt2L._AC_SL1500_.jpg"]',4.2,94,'hasdata','https://www.amazon.com/dp/B0CG4HJ2SK',1778333657,1,NULL,'["【Material】Gray Thickened Glass Container +Bronze Plastic Painted Top Pump.","【Multi-Application】This plant mister can be used for general spraying both indoor and outdoor, gardening, general cleaning.","【Comfortable Design】Small pressure watering can with a convenient finger holder, it''s more comfortable to spray plants in this way.","【Small House Plants】This small watering can is perfect to water small house plants such as succulent plants, ferns, orchids, air plants etc.","【Approximate Dimensions (in inches)】3.15\" W X 6.5\" H X 3.15\" D."]');
