INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0B8F6KDHN','Reusable Beeswax Wrap - 9 Pack Beeswax Wraps for Food, Eco-Friendly Beeswax Food Wraps, Bread Sandwich Wrapper - Organic, Sustainable, Zero Waste, Reusable Plastic-Free Food Storage Wrap, 1XL, 3M, 5S','reusable-beeswax-wrap-9-pack-beeswax-wraps-for-food-eco-frie-b0b8f6kdhn','BYTTME','Sustainable Living',51.82,'【NATURAL ECO-FRIENDLY INGREDIENTS】: Our Reusable Beeswax Wrap are made from Organic cotton, Organic jojoba oil, Natural Harvest beeswax, and Tree resin. These beeswax wraps are all certified with European LFGB, the fabric is GOTS certified(Global Organic Textile Standard) and the packaging is made from 100% recycled paper. Reusable beeswax food wrap is sustainable and a natural alternative to plastic wraps and cling film for food!. 【MULTIPLE SIZES FOR A SET】: This set come with 9 Packs Beeswax Wrap for your daily uses: 1 X-Large(14.3x14.3"), 3 Medium(11.5x11.5") and 5 Small(7.5x7.5") beeswax wraps. Different sizes can cover different foods or bowls depending on your demand. It''s great to wrap food leftovers or food you take to the picnic, your office sandwich, in kids lunchboxes or to store well for your fresh produce, fruits, snacks, cheese, bread, sandwiches, nuts and more!. 【KEEP FOOD FRESHER FOR LONGER】: Unique self-adhesive design & double coating make our beeswax wrap more durable and long lasting. Our reusable food wraps with beeswax are not only environmentally friendly and highly sustainable it also makes sure your food stays fresher for longer. Beeswax wraps for food can create air tight seals which will keep your food fresh and delightful. Now you can keep your fruits, vegetables, sandwich, cheese and leftovers wrapped up and maintain flavor of your food.. 【REUSABLE & WASHABLE】: Use the warmth of your hands to soften the beeswax wrap and form over a container or foods. Wash in cool water with mild soap and air dry then use again. Our high grade beeswax food wraps will last up to a year with regular use. Keep food wraps away from heat and don''t put in the dishwasher. Our reusable food wrap is biodegradable, sustainable and washable. Say goodbye to plastic wrap and cling wrap, and it''s a great addition in your eco-friendly kitchen items.. 【GREEN LIFE】: It''s never too late to promote a plastic-free life with these Eco-Friendly reusable beeswax wrap. The reusable food wraps is a sustainable product that is good in quality and easy to use, also fine for the environment. Ideal for an organic lifestyle and a healthy food lifestyle. Also it’s a good gift for your family or friends to protect our earth!','["https://m.media-amazon.com/images/I/816mbJg3aLL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71LBFhgzpRL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81d-5qiBSoL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71STNjOQrAL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71w9FieMeIL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81LDcQ-GseL._AC_SL1500_.jpg"]',4.5,1456,'hasdata','https://www.amazon.com/dp/B0B8F6KDHN',1778333814,1,NULL,'["【NATURAL ECO-FRIENDLY INGREDIENTS】: Our Reusable Beeswax Wrap are made from Organic cotton, Organic jojoba oil, Natural Harvest beeswax, and Tree resin. These beeswax wraps are all certified with European LFGB, the fabric is GOTS certified(Global Organic Textile Standard) and the packaging is made from 100% recycled paper. Reusable beeswax food wrap is sustainable and a natural alternative to plastic wraps and cling film for food!","【MULTIPLE SIZES FOR A SET】: This set come with 9 Packs Beeswax Wrap for your daily uses: 1 X-Large(14.3x14.3\"), 3 Medium(11.5x11.5\") and 5 Small(7.5x7.5\") beeswax wraps. Different sizes can cover different foods or bowls depending on your demand. It''s great to wrap food leftovers or food you take to the picnic, your office sandwich, in kids lunchboxes or to store well for your fresh produce, fruits, snacks, cheese, bread, sandwiches, nuts and more!","【KEEP FOOD FRESHER FOR LONGER】: Unique self-adhesive design & double coating make our beeswax wrap more durable and long lasting. Our reusable food wraps with beeswax are not only environmentally friendly and highly sustainable it also makes sure your food stays fresher for longer. Beeswax wraps for food can create air tight seals which will keep your food fresh and delightful. Now you can keep your fruits, vegetables, sandwich, cheese and leftovers wrapped up and maintain flavor of your food.","【REUSABLE & WASHABLE】: Use the warmth of your hands to soften the beeswax wrap and form over a container or foods. Wash in cool water with mild soap and air dry then use again. Our high grade beeswax food wraps will last up to a year with regular use. Keep food wraps away from heat and don''t put in the dishwasher. Our reusable food wrap is biodegradable, sustainable and washable. Say goodbye to plastic wrap and cling wrap, and it''s a great addition in your eco-friendly kitchen items.","【GREEN LIFE】: It''s never too late to promote a plastic-free life with these Eco-Friendly reusable beeswax wrap. The reusable food wraps is a sustainable product that is good in quality and easy to use, also fine for the environment. Ideal for an organic lifestyle and a healthy food lifestyle. Also it’s a good gift for your family or friends to protect our earth!"]');
