INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FXT14S5W','3-Pack Magnetic Cable Clips, Detachable Cable Organizer, Auto Open & Close Design, Self-Adhesive Cord Holder, Universal Wire Organizer Compatible with Round & Flat Cables, for Home, Office, Desk, Car','3-pack-magnetic-cable-clips-detachable-cable-organizer-auto-b0fxt14s5w','DockDuck','Cable & Device Management',5.97,'[DETACHABLE & MAGNETIC DESIGN] Unique detachable structure allows flexible placement and space-saving storage. Strong magnetic closure securely grips cables without slipping, enabling instant one-hand use—no manual opening or closing required for maximum convenience.. [NO MANUAL OPERATION FOR HASSLE-FREE USE] Fully automatic magnetic adsorption eliminates fiddly clips or lids. Simply place cables near the organizer for instant holding, remove effortlessly with one hand. Ideal for fast, easy daily cable management at home, office, or car.. [UNIVERSAL FOR ROUND & FLAT CABLES] Wide magnetic surface works perfectly with all round cables and flat cables, compatible with phone chargers, USB cords, earphone wires, data lines, and more. No alignment needed—cables are held securely from any angle.. [RESIDUE-FREE ADHESIVE & TOOL-FREE INSTALLATION] Strong self-adhesive sticks firmly to wood, glass, plastic, metal, and marble. Drill-free installation in seconds, removes cleanly without damage, sticky residue, or scratches. Press firmly for 30 seconds and wait 24 hours for best adhesion.. [COMPACT MULTI-SCENE USE & DURABLE 3-PACK] Mini size (0.39"L x 0.31"W) fits desk edges, nightstands, car dashboards, and more. Lightweight, portable, and minimalist black style blends any decor. Sturdy PVC + magnet material ensures long life, 3-pack covers all your cable organization needs.','["https://m.media-amazon.com/images/I/61f8Rmc2lDL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/81rP+5ENgbL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71xtzCHGvWL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71TnjygyCuL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/710u+e1qb9L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/810Ge0HXrtL._AC_SL1500_.jpg"]',4.5,2,'hasdata','https://www.amazon.com/dp/B0FXT14S5W',1778334072,1,NULL,'["[DETACHABLE & MAGNETIC DESIGN] Unique detachable structure allows flexible placement and space-saving storage. Strong magnetic closure securely grips cables without slipping, enabling instant one-hand use—no manual opening or closing required for maximum convenience.","[NO MANUAL OPERATION FOR HASSLE-FREE USE] Fully automatic magnetic adsorption eliminates fiddly clips or lids. Simply place cables near the organizer for instant holding, remove effortlessly with one hand. Ideal for fast, easy daily cable management at home, office, or car.","[UNIVERSAL FOR ROUND & FLAT CABLES] Wide magnetic surface works perfectly with all round cables and flat cables, compatible with phone chargers, USB cords, earphone wires, data lines, and more. No alignment needed—cables are held securely from any angle.","[RESIDUE-FREE ADHESIVE & TOOL-FREE INSTALLATION] Strong self-adhesive sticks firmly to wood, glass, plastic, metal, and marble. Drill-free installation in seconds, removes cleanly without damage, sticky residue, or scratches. Press firmly for 30 seconds and wait 24 hours for best adhesion.","[COMPACT MULTI-SCENE USE & DURABLE 3-PACK] Mini size (0.39\"L x 0.31\"W) fits desk edges, nightstands, car dashboards, and more. Lightweight, portable, and minimalist black style blends any decor. Sturdy PVC + magnet material ensures long life, 3-pack covers all your cable organization needs."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FFM3GKZQ','6 Pack Magnetic Cable Clips [1s Open/Lock], Laitver Cord Organizer Holder Strong Adhesive Desk Cable Management- Organize Charging Cords Neatly for Home, Office, Car,Desk, Nightstand','6-pack-magnetic-cable-clips-1s-openlock-laitver-cord-organiz-b0ffm3gkzq','Symeno Select','Cable & Device Management',2.99,'Versatile & Flexible Combination: Laitver magnetic cable clips include 4 single cable clips + 2 double cable clips + 2 plastic bases, which can easily meet the needs of organizing 8 cables. The dual cable clip can separate two cables to prevent entanglement, the single cable clip can fix one cable in place, which is ideal for thin cables. The two cable clips can be moved freely on the plastic card base. Whether used alone or in combination, they can meet your various usage scenarios.. Strong Magnetic Suction & One-handed Operation: Each cable clip adopts a unique magnetic opening and closing design, the magnet is automatically and accurately aligned, saying goodbye to the cumbersome traditional cable clip. You can fix or release the charging cable, HDMI, USB and other types of cables with one-handed gently pressing, which is more energy-saving and efficient than the traditional grommets. Side clever design, easy to open, no longer afraid of hurting your nails!. Durable & Easy to Install: Magnetic cable clips are made of tough, hard-wearing ABS plastic for long-lasting use. Contains a reusable adhesive that can be applied to any smooth surface by removing the protective film. It leaves virtually no adhesive residue and protects the surface as well as new. Tip: Before installation, clean the mounting surface thoroughly, put on the clip and press firmly for 20 seconds, and leave it for 24 hours to achieve the best adhesion effect.. Neat & Widely Adaptable: Cord organizer holder with 7.5mm diameter slot design, perfectly adapts to a wide range of cables up to 7.5mm diameter, including USB, HDMI, mobile phone charging cables, wired headphones, ethernet cables and power cables of various electronic devices. It effectively prevents cables from getting tangled and knotted, and at the same time, it is easy to plug and unplug, reducing the risk of damage caused by pulling.. Compact & Multi-Scene Use: Compact and exquisite cable clips save space and can be cleverly integrated into various environments, whether it is the living room, kitchen, office, wall, bedside table or even the car, they are a good helper to keep tidy. Whether you are busy at work or in a leisurely time at home, these wire clips can be like a caring little assistant to keep every corner in order!','["https://m.media-amazon.com/images/I/81cLsIpfRgL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71TlPCE8uML._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61yT-N6jWcL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61xHM6WDYKL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/713UB1Z+9CL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71Be1ajPBkL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61xV0lXVgNL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71XCLvkfH7L._AC_SL1500_.jpg"]',4.7,998,'hasdata','https://www.amazon.com/dp/B0FFM3GKZQ',1778334079,1,NULL,'["Versatile & Flexible Combination: Laitver magnetic cable clips include 4 single cable clips + 2 double cable clips + 2 plastic bases, which can easily meet the needs of organizing 8 cables. The dual cable clip can separate two cables to prevent entanglement, the single cable clip can fix one cable in place, which is ideal for thin cables. The two cable clips can be moved freely on the plastic card base. Whether used alone or in combination, they can meet your various usage scenarios.","Strong Magnetic Suction & One-handed Operation: Each cable clip adopts a unique magnetic opening and closing design, the magnet is automatically and accurately aligned, saying goodbye to the cumbersome traditional cable clip. You can fix or release the charging cable, HDMI, USB and other types of cables with one-handed gently pressing, which is more energy-saving and efficient than the traditional grommets. Side clever design, easy to open, no longer afraid of hurting your nails!","Durable & Easy to Install: Magnetic cable clips are made of tough, hard-wearing ABS plastic for long-lasting use. Contains a reusable adhesive that can be applied to any smooth surface by removing the protective film. It leaves virtually no adhesive residue and protects the surface as well as new. Tip: Before installation, clean the mounting surface thoroughly, put on the clip and press firmly for 20 seconds, and leave it for 24 hours to achieve the best adhesion effect.","Neat & Widely Adaptable: Cord organizer holder with 7.5mm diameter slot design, perfectly adapts to a wide range of cables up to 7.5mm diameter, including USB, HDMI, mobile phone charging cables, wired headphones, ethernet cables and power cables of various electronic devices. It effectively prevents cables from getting tangled and knotted, and at the same time, it is easy to plug and unplug, reducing the risk of damage caused by pulling.","Compact & Multi-Scene Use: Compact and exquisite cable clips save space and can be cleverly integrated into various environments, whether it is the living room, kitchen, office, wall, bedside table or even the car, they are a good helper to keep tidy. Whether you are busy at work or in a leisurely time at home, these wire clips can be like a caring little assistant to keep every corner in order!"]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0FN4S5W3S','11PCS Cable Management Cord Holder Organizer, Magnetic Cable Clips Adhesive Wire Keeper, Under Desk for Bedside Nightstand Table Desktop USB Wall Car Office Workspace Accessories (Black)','11pcs-cable-management-cord-holder-organizer-magnetic-cable-b0fn4s5w3s','ITUGOU','Cable & Device Management',12.99,'Strong Adhesive: The magnetic swivel cable organizer is made of PA material, while the silicone cable manager is made of silicone material with an upgraded adhesive. They securely hold cables, cords, and wires in place, leaving no residue or damage when removed. Suitable for clean surfaces such as tables, walls, cabinets, wood, ceramic, and metal.. Product Contents: Our cable management system includes six magnetic swivel clips and five silicone clips, neatly stored in a compact box.. Wide Applications: Our clips are suitable for power cords, charging cables, CAT-6 cables, USB cables, network cables, and laptop power cables in both home and office environments, and are particularly suitable for metal, glass, and wood surfaces.. Warm Tips: Before using the light clip hook, be sure to clean the mounting surface with an alcohol pad, then apply and press firmly for 30 seconds. Use after 24 hours for optimal adhesion.','["https://m.media-amazon.com/images/I/71raDBs2VaL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61Fl7+LWkjL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/610jswT0oYL._AC_.jpg","https://m.media-amazon.com/images/I/713t23ZvlCL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51W4SxOM+UL._AC_.jpg","https://m.media-amazon.com/images/I/41rlz9kYeAL._AC_.jpg","https://m.media-amazon.com/images/I/61Mohg7NeNL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/71cM8ZY9yCL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/612XGFkylLL._AC_SL1500_.jpg"]',4.6,36,'hasdata','https://www.amazon.com/dp/B0FN4S5W3S',1778334085,1,NULL,'["Strong Adhesive: The magnetic swivel cable organizer is made of PA material, while the silicone cable manager is made of silicone material with an upgraded adhesive. They securely hold cables, cords, and wires in place, leaving no residue or damage when removed. Suitable for clean surfaces such as tables, walls, cabinets, wood, ceramic, and metal.","Product Contents: Our cable management system includes six magnetic swivel clips and five silicone clips, neatly stored in a compact box.","Wide Applications: Our clips are suitable for power cords, charging cables, CAT-6 cables, USB cables, network cables, and laptop power cables in both home and office environments, and are particularly suitable for metal, glass, and wood surfaces.","Warm Tips: Before using the light clip hook, be sure to clean the mounting surface with an alcohol pad, then apply and press firmly for 30 seconds. Use after 24 hours for optimal adhesion."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0CVR8RLYY','Maveek 5 Pcs Magnetic Cord Holder Cable Management, Strong Cable Clips Magnets Metal Plate, Adhesive Wire Organizers for Nightstand Desktop Wall Kitchen USB LAN (Black)','maveek-5-pcs-magnetic-cord-holder-cable-management-strong-ca-b0cvr8rlyy','Maveek','Cable & Device Management',9.99,'【Superior Material】The body is made of high quality silicone, which can support cables up to 0.2 inch (5 mm) in diameter. The overall product dimensions is 0.79''''(L)*0.79''''(W)*0.4''''(H). Each magnetic cable clip contains 2 strong magnetic magnets, which can firmly attached even if you pull the cable.. 【Modern Design】The magnetic clip is bite-sized, so even if installed on either side of a desk or nightstand, it is still aesthetically pleasing. These cable clips can be easily used in offices, kitchens, or cars. Very convenient and efficient.. 【Unlimited Location】It comes with a metal plate with strong double-sided tape, so even if the area you want to store the cable does not attract magnets, you can easily solve it by using a metal plate. It is easy to apply by removing the adhesive tape without any tools.. 【Easy Life】 Prevent USB cables and charging cables from being lost or dropped in daily life. Say goodbye to chaotic data cables, headphone cables, power cables, etc. in the office, kitchen, car, etc. Recommended for people with messy cables on the table.. 【Easy To Use】 You can pull the cable with one hand and freely adjust the length of the cable, without the hassle of frequently finding clips to fix the cable.','["https://m.media-amazon.com/images/I/61kXXZxSlrL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61f-Z11b2UL._AC_SL1480_.jpg","https://m.media-amazon.com/images/I/618F3NdnopL._AC_SL1480_.jpg","https://m.media-amazon.com/images/I/71PsTw3zUNL._AC_SL1480_.jpg","https://m.media-amazon.com/images/I/715QuFt1VDL._AC_SL1480_.jpg","https://m.media-amazon.com/images/I/61EQi7wmONL._AC_SL1480_.jpg","https://m.media-amazon.com/images/I/614h+5qTe7L._AC_SL1480_.jpg","https://m.media-amazon.com/images/I/61wG7W8e0GL._AC_SL1500_.jpg"]',4.8,228,'hasdata','https://www.amazon.com/dp/B0CVR8RLYY',1778334101,1,NULL,'["【Superior Material】The body is made of high quality silicone, which can support cables up to 0.2 inch (5 mm) in diameter. The overall product dimensions is 0.79''''(L)*0.79''''(W)*0.4''''(H). Each magnetic cable clip contains 2 strong magnetic magnets, which can firmly attached even if you pull the cable.","【Modern Design】The magnetic clip is bite-sized, so even if installed on either side of a desk or nightstand, it is still aesthetically pleasing. These cable clips can be easily used in offices, kitchens, or cars. Very convenient and efficient.","【Unlimited Location】It comes with a metal plate with strong double-sided tape, so even if the area you want to store the cable does not attract magnets, you can easily solve it by using a metal plate. It is easy to apply by removing the adhesive tape without any tools.","【Easy Life】 Prevent USB cables and charging cables from being lost or dropped in daily life. Say goodbye to chaotic data cables, headphone cables, power cables, etc. in the office, kitchen, car, etc. Recommended for people with messy cables on the table.","【Easy To Use】 You can pull the cable with one hand and freely adjust the length of the cable, without the hassle of frequently finding clips to fix the cable."]');
INSERT INTO "catalog_cache" ("id","name","slug","brand","category","price","description","images_json","rating","review_count","source","source_url","scraped_at","in_stock","variants_json","tags_json") VALUES('B0DP54X9DZ','18 Pack Cord Organizer Holder,Magnetic Cable Clips Management, Easy Adhesive Phone USB Charger Cord Keeper, Hide Or Organize Desk Cable for Kitchen, Office, Car, Nightstand （Black）','18-pack-cord-organizer-holdermagnetic-cable-clips-management-b0dp54x9dz','Boazimy','Cable & Device Management',96.24,'Suitable For All Kinds Of Cables: Diameter of about 0.3in allows to hold most cords, such as Type-C charger cords, iPhone charger cables, USB cables, kitchen appliance power, headphone cords. Magnetic Locking: Our magnetic clips are designed to provide a stable hold on cables, ensuring that they stay in suitable place, more convenient to pull the cables out for smoothly using. No-Residue or Damage: Magnetic cable clamps remove without residue. This way, even if it''s not placed correctly, the cable clamp can be adjusted instantly, making cable management simple and reusable multiple times. Conveniently designed backing for use on a variety of smooth surface materials including wood, metal, plastic, and leather. Keep it Neat & Tidy: Cable organizers hold wires in place, keeping cables hidden and close at hand for easy access, creating a tidy mood. Kindly Installation Tips: Please make sure the surface is dry and smooth before pasting, and then press continuously for 30 seconds. After completion, it is recommended to wait 12-24 hours for better adhesion. Thank you for choosing our products, we are happy to serve you at any time','["https://m.media-amazon.com/images/I/71tkLC+1VTL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/619qhvnPcoL._AC_SL1001_.jpg","https://m.media-amazon.com/images/I/61TlLCCC9CL._AC_SL1001_.jpg","https://m.media-amazon.com/images/I/61zqOxd5yGL._AC_SL1001_.jpg","https://m.media-amazon.com/images/I/61QsAY8h4aL._AC_SL1001_.jpg","https://m.media-amazon.com/images/I/611rBix7snL._AC_SL1001_.jpg","https://m.media-amazon.com/images/I/61QoQX8tmVL._AC_SL1001_.jpg"]',4.2,606,'hasdata','https://www.amazon.com/dp/B0DP54X9DZ',1778334108,1,NULL,'["Suitable For All Kinds Of Cables: Diameter of about 0.3in allows to hold most cords, such as Type-C charger cords, iPhone charger cables, USB cables, kitchen appliance power, headphone cords","Magnetic Locking: Our magnetic clips are designed to provide a stable hold on cables, ensuring that they stay in suitable place, more convenient to pull the cables out for smoothly using","No-Residue or Damage: Magnetic cable clamps remove without residue. This way, even if it''s not placed correctly, the cable clamp can be adjusted instantly, making cable management simple and reusable multiple times. Conveniently designed backing for use on a variety of smooth surface materials including wood, metal, plastic, and leather","Keep it Neat & Tidy: Cable organizers hold wires in place, keeping cables hidden and close at hand for easy access, creating a tidy mood","Kindly Installation Tips: Please make sure the surface is dry and smooth before pasting, and then press continuously for 30 seconds. After completion, it is recommended to wait 12-24 hours for better adhesion. Thank you for choosing our products, we are happy to serve you at any time"]');
